// Reviewed answers: every question re-judged against Microsoft product behaviour and documentation,
// with an explanation and a knowledge-point tag. Keyed by ExamTopics question ID. Hand-maintained; the
// scraper never touches this file. verdict: confirmed (agrees with ExamTopics) | corrected (differs).
window.REVIEWED = {
"1007775": {"exam": "AB-620", "n": 1, "boxes": ["Define Data Loss Prevention (DLP) policies.", "Configure content moderation filters.", "Add custom prompt modifications."], "verdict": "corrected", "confidence": "medium", "kp": "Responsible AI & content control", "why": "The case study lists three configuration requirements: DLP policies must be enforced, Responsible AI content moderation filters must be enabled, and prompt modifications must enforce tone, disclaimers and refusals. Those are the three actions, ordered from tenant/environment governance (DLP) to platform safety (moderation filters) to agent-level behaviour (prompt modifications). Adversarial testing is a verification step, not a configuration that meets a requirement, and disabling generative answers or integrating Purview is not required."},
"1020430": {"exam": "AB-620", "n": 2, "answer": "AC", "verdict": "corrected", "confidence": "high", "kp": "Prompts & generative answers", "why": "Prompt-driven responses in Copilot Studio come from a prompt (AI Builder prompt tool) whose configuration lets you pick the model from the Microsoft Foundry model catalog, so selecting an approved model there is what enforces the governance requirement. The reusable instruction template must stay applied so the structured response keeps its tone and format. Writing \"use only approved models\" inside the instructions, enabling citations, grounding on Azure AI Search or republishing cannot change which model generates the response. #52 is this question without option A: only there is the instruction line the answer, by elimination. The pooled community vote leans to CF because it counts #52's voters, who never saw option A; this copy's own voters favour AC.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/bring-your-own-model-prompts"},
"1020431": {"exam": "AB-620", "n": 3, "boxes": ["Add a knowledge source.", "Select a real-time connector from the Add knowledge dialog.", "Sign in and create a new connection or reuse an existing connection.", "Select the tables to include as the knowledge source.", "Add the connector to the agent."], "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Real-time connector knowledge is added from the agent's Knowledge page: choose Add knowledge, pick the connector in the dialog, sign in to create or reuse a connection, choose the tables to expose, then add it to the agent. The connection must exist before tables can be listed, and tables are chosen before the source is attached."},
"1007779": {"exam": "AB-620", "n": 4, "answer": "AD", "verdict": "confirmed", "confidence": "medium", "kp": "Knowledge sources & grounding", "why": "Internal policy documents in SharePoint are added as a knowledge source, and partner content is brought in through a Microsoft Graph (Copilot) connector so it is indexed with its permissions. Writing a Q&A topic per document contradicts the case study's rule against manually authored Q&A, and unrestricted web search violates the content-control requirements."},
"1007780": {"exam": "AB-620", "n": 5, "answer": "BC", "verdict": "confirmed", "confidence": "medium", "kp": "Responsible AI & content control", "why": "A prompt modification on the generative answers node makes every AI-generated answer carry the disclaimer, and a dedicated disclaimer topic that runs first delivers it consistently without touching each topic. Editing every topic breaks the case study's rule against manual per-topic edits, a greeting shows the disclaimer only once, and disabling generative answers defeats the purpose."},
"1007781": {"exam": "AB-620", "n": 6, "boxes": ["Allow anonymous access.", "Require customer sign-in using an account.", "Require internal agent sign-in using Microsoft Entra ID."], "verdict": "confirmed", "confidence": "high", "kp": "Security, authentication & governance", "why": "General questions such as baggage allowance are explicitly allowed anonymously; anything touching personal data such as upcoming trips requires the customer to sign in; internal staff authenticate with Microsoft Entra ID. Author credentials must never be used for data access."},
"1007782": {"exam": "AB-620", "n": 7, "boxes": ["Add the connector as a tool in the agent.", "Create or reuse a connection for the connector.", "Map topic variables to the tool inputs."], "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "A connector action becomes usable in topics once it is added to the agent as a tool; it runs under a connection that must be created or reused; and the tool's inputs are filled at runtime by mapping topic variables to them. Adding it as a knowledge source would only make it a grounding source, not a callable action."},
"1007783": {"exam": "AB-620", "n": 8, "boxes": ["Select Add knowledge from the agent Knowledge experience.", "Select the real-time connector from the Add knowledge dialog.", "Select Sign in and create a new connection or reuse an existing connection.", "Select the tables to include as the knowledge source.", "Select Add to agent to complete the connection."], "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Same flow as adding any real-time connector knowledge source: open Add knowledge, choose the connector, authenticate, pick the tables, then Add to agent. Tables cannot be listed until a connection exists."},
"1007784": {"exam": "AB-620", "n": 9, "boxes": ["Disable the flow.", "Resubmit the run.", "Review the Activity history."], "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Turning the flow off stops new runs while you fix the connection; a failed run can be resubmitted from its run page once the authentication is repaired; the run history (activity) shows whether the latest runs succeeded. Deleting the flow or cancelling one run does not stop future triggers, and analytics is aggregated rather than immediate."},
"1007785": {"exam": "AB-620", "n": 10, "boxes": ["Create a new agent flow artifact in the environment.", "Configure the invocation trigger that allows the agent to call the agent flow.", "Configure the actions that implement the required behavior.", "Validate the agent flow behavior with representative test runs.", "Make the agent flow available for agent usage."], "verdict": "confirmed", "confidence": "medium", "kp": "Agent flows", "why": "An agent flow starts with the \"When an agent calls the flow\" trigger, then the actions that do the work; it is tested with representative runs before it is published and added to the agent so the agent can invoke it. Making it available before it is verified would expose an untested flow."},
"1007786": {"exam": "AB-620", "n": 11, "boxes": ["Use the action's response outputs in subsequent steps.", "Allow the action to wait for and return a response before continuing.", "Add a human approval action."], "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Human-in-the-loop flows use an approval action: it pauses the run until a person responds, its outputs (decision, comments) are available to the following steps, and because the action waits for the response the same run continues instead of a new run being triggered."},
"1007787": {"exam": "AB-620", "n": 12, "boxes": ["Add a text input parameter.", "Add a text output parameter."], "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Data passes from the agent into a flow through input parameters defined on the agent trigger, and back to the agent through output parameters on the \"Respond to the agent\" action. Internal variables and run history are not visible to the agent."},
"1007788": {"exam": "AB-620", "n": 13, "boxes": ["Connect to a Power Platform connector.", "Connect to a Power Platform connector.", "Upload a file to Agents Knowledge Base.", "Create a manual response in the topic."], "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Live, changing records in Dataverse and Dynamics 365 are read through a Power Platform connector at runtime; a static PDF is uploaded as file knowledge and answered generatively; a fixed welcome message is simply authored in the topic. A generative answer without enterprise data cannot report balances or shipping status."},
"1007789": {"exam": "AB-620", "n": 14, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Empty or unexpected values between an agent and a flow almost always mean the input and output parameter definitions do not line up: names, types or the mapping of topic variables to the flow's outputs. Checking run history only shows symptoms, Parse JSON does not fix a missing output, and republishing changes nothing."},
"1007790": {"exam": "AB-620", "n": 15, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Grounding inside a topic is done with a generative answers node, where you can select the specific knowledge sources that node searches. Agent-level SharePoint knowledge is used by orchestration, not scoped to a topic, and a prompt instruction or longer responses do not ground anything."},
"1007791": {"exam": "AB-620", "n": 16, "boxes": ["Add required headers to the HTTP request.", "Set the method to GET in the HTTP request.", "Select JSON data type and save response to a variable."], "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "The Send HTTP request node authenticates through request headers (for example an API key or bearer token), retrieves status with GET, and parses the response by choosing the JSON data type with a schema and saving it to a variable the topic reuses."},
"1007792": {"exam": "AB-620", "n": 17, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Security, authentication & governance", "why": "Authenticate with Microsoft Entra ID restricts the agent to users of the tenant and enforces sign-in. A public website publish or personal accounts would let outsiders in, and Require Secure Access only protects the web channel's token exchange."},
"1007793": {"exam": "AB-620", "n": 18, "boxes": ["Publish the agent.", "Configure and enable the agent's target integration channel.", "Retrieve current agent configuration values.", "Implement the Microsoft 365 Agents SDK in the app using the agent configuration.", "Validate the end-to-end conversation workflow in a test environment.", "Deploy the web app to production."], "verdict": "corrected", "confidence": "medium", "kp": "Channels & publishing", "why": "The agent must be published first; the Web app or Native app channel is then enabled, which is where the Microsoft 365 Agents SDK connection string is copied from (or the environment ID, tenant ID and schema name under Settings > Advanced > Metadata); those values are used to implement the Agents SDK client, which the docs have you test with the sample app before integrating it into your own UI and deploying. Whether the configuration values are read before or after enabling the channel is the one debatable step.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/publication-integrate-web-or-native-app-m365-agents-sdk"},
"1007794": {"exam": "AB-620", "n": 19, "answer": "CE", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Solution-based ALM means creating a custom (unmanaged) solution, adding the existing agent with its dependencies, and exporting that solution to import elsewhere. Converting to managed is done at export time, not a prerequisite; removing topics or exporting a channel is not part of the process."},
"1007795": {"exam": "AB-620", "n": 20, "boxes": ["Retrieve indexed content", "Respect existing permissions.", "Prevent transactional updates."], "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "A Copilot (Graph) connector knowledge source answers from content indexed into Microsoft Graph, honours the source system's permissions for the signed-in user, and is read-only: it never performs transactions. Live calls and writes are the job of tools, not knowledge."},
"1007796": {"exam": "AB-620", "n": 21, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Retrying without any failure handling still ends silently when the retries are exhausted and never sends the required notification with error details."},
"1007797": {"exam": "AB-620", "n": 22, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Agent flows", "why": "Run-after conditions let you add a branch that executes when the previous action fails or times out, which is the mechanism for controlled, predictable failure handling (and where the notification with error details is sent). Without it, a failure ends the run silently."},
"1007798": {"exam": "AB-620", "n": 23, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Sending a notification that contains the error details satisfies both requirements: the failure is surfaced rather than silent, and the message carries the details."},
"1007776": {"exam": "AB-620", "n": 24, "boxes": ["Compliant", "Non-compliant", "Non-compliant", "Non-compliant"], "verdict": "confirmed", "confidence": "high", "kp": "Security, authentication & governance", "why": "The case study allows anonymous access for general inquiries, so that decision is compliant. Open web search ignores the requirement to ground on approved sources, relying on default filters alone skips the mandated prompt modifications for tone and disclaimers, and a shared admin credential breaks the rule that user identity must be used for data access."},
"1007777": {"exam": "AB-620", "n": 25, "answer": "AD", "verdict": "confirmed", "confidence": "high", "kp": "Responsible AI & content control", "why": "Before publishing to any channel you set prompt modifications at the agent level so tone, disclaimers and refusals apply everywhere, and you enforce Power Platform DLP policies to block unauthorized connectors. Per-topic or per-channel moderation settings contradict the case study's consistency requirement."},
"1007778": {"exam": "AB-620", "n": 26, "answer": "BC", "verdict": "confirmed", "confidence": "high", "kp": "Responsible AI & content control", "why": "Disclaimers belong in the prompt instructions so they appear consistently in every generative response, and formatting must use Markdown because HTML is not supported. Putting disclaimer text in individual topics is exactly the manual editing the case study forbids."},
"1021099": {"exam": "AB-620", "n": 27, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Terminating the flow on error stops it silently and sends no notification, so neither requirement is met."},
"1021100": {"exam": "AB-620", "n": 28, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Indexed content from a non-Microsoft system is exposed to agents through a Copilot connector (Microsoft Graph connector) added as a knowledge source, which keeps the source's authorization. Tools and per-question API calls retrieve live data for actions rather than grounding generative answers on an index."},
"1021101": {"exam": "AB-620", "n": 29, "boxes": ["Retrieve data without indexing.", "Use existing permissions.", "Use real-time connector."], "verdict": "corrected", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "A real-time connector knowledge source queries the system when the user asks, so the data is never copied into an index, the source system's own permissions keep applying, and the system is called at runtime. Mapped by meaning: avoiding an index copy is retrieving without indexing, access control is existing permissions, and runtime access is the real-time connector itself.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/knowledge-real-time-connectors"},
"1021102": {"exam": "AB-620", "n": 30, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Once an administrator has set up the Copilot connector, the builder only adds that enterprise knowledge source to the agent's knowledge. Re-uploading documents duplicates content, a custom connector or tool would make it a transactional call instead of grounding."},
"1021103": {"exam": "AB-620", "n": 31, "boxes": ["Define environment variables in the solution.", "Define environment variables in the solution.", "Define environment variables in the solution."], "verdict": "confirmed", "confidence": "medium", "kp": "ALM & deployment", "why": "Environment variables are the ALM mechanism for configuration that differs per environment: their values are supplied at import, they live outside the agent definition, and the same solution then runs as its own agent instance in each environment with that environment's values. Publishing different agent versions or hardcoding values would mean changing the solution contents, which the requirements forbid."},
"1021104": {"exam": "AB-620", "n": 32, "boxes": ["Use a secret environment variable type to allow for runtime resolution.", "Environment variables are read-only in Copilot Studio.", "The agent must be republished for the updated value to be effective at runtime."], "verdict": "corrected", "confidence": "high", "kp": "ALM & deployment", "why": "Secret environment variables are retrieved at runtime, so a rotated secret takes effect without republishing. Environment variables are read-only in Copilot Studio: authors can see them in the Variables panel but administrators change values in Power Apps. For every other type the published agent includes the values set when it was published, so after an administrator updates a non-secret value the agent must be republished for the change to take effect at runtime (Microsoft Learn, \"Variables overview\", Environment variables section).", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/authoring-variables-about"},
"1021105": {"exam": "AB-620", "n": 33, "boxes": ["Endpoint and authentication", "Input and mapping"], "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "An HTTP action is configured with the endpoint URL and the authentication it must present; a data action (such as a Dataverse row operation) is configured with the inputs and the mapping of fields to the data it processes."},
"1021106": {"exam": "AB-620", "n": 34, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Security, authentication & governance", "why": "Data policies (Power Platform DLP) are the admin control that blocks disallowed connectors and insecure data flows across agents and reports violations. Telemetry, analytics and FAQs only observe or describe; they do not enforce."},
"1021107": {"exam": "AB-620", "n": 35, "boxes": ["Wait for a response and branch based on the decision.", "Wait for a response and capture inputs."], "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "An approval stage waits for the human decision and then branches on approve/reject; an information-collection stage waits for the person's response and captures the submitted values so execution can continue with them."},
"1021108": {"exam": "AB-620", "n": 36, "boxes": ["Select Activity.Text in the Input field.", "Select Search only selected sources.", "Clear Allow the AI to use its own general knowledge."], "verdict": "confirmed", "confidence": "high", "kp": "Prompts & generative answers", "why": "In a generative answers node, Activity.Text passes the user's latest message as the query; Search only selected sources limits the node to the knowledge you pick; clearing the general-knowledge option stops the model from answering from its training data, so responses stay within approved enterprise content."},
"1021109": {"exam": "AB-620", "n": 37, "answer": "CD", "verdict": "confirmed", "confidence": "high", "kp": "Topics & conversation design", "why": "An Ask with Adaptive Card node collects structured input in one step and stores the submitted field values in topic variables; the card needs input fields and an Action.Submit button to return them. A Message node cannot collect input, and Action.Execute is not supported for Copilot Studio card submissions."},
"1007799": {"exam": "AB-620", "n": 38, "boxes": ["Enable generative orchestration.", "Add a tool node.", "Add a tool node."], "verdict": "corrected", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "Letting the agent decide when to run a tool from the user's input is exactly what generative orchestration does. Running a specific agent flow at a fixed step, and calling a connector action during a conversation, are both done by adding a tool node to the topic. A question node asking the user to pick a tool and an Adaptive Card do not invoke tools.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/advanced-connectors"},
"1007833": {"exam": "AB-620", "n": 39, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Prompts & generative answers", "why": "Removing the generative answers node removes the grounding on the configured knowledge sources; a custom prompt alone cannot keep using those sources or the connector security controls. The formatting requirement is met by adding a prompt modification to the node, not by deleting it."},
"1007800": {"exam": "AB-620", "n": 40, "boxes": ["Custom connector", "HTTP request"], "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "The case study states that internal APIs without a prebuilt connector, such as the reservation system, must use custom connectors, while lightweight external APIs such as flight status and weather may be called with HTTP request nodes."},
"1007801": {"exam": "AB-620", "n": 41, "boxes": ["Use a tool node.", "Use a generative answers node.", "Use a tool node."], "verdict": "corrected", "confidence": "medium", "kp": "Agent flows", "why": "The case study requires reusable logic to live in agent flows and forbids duplicated logic, so a topic that repeats steps already built in a flow should call that flow through a tool node rather than rebuild them, and a step that runs a reusable rebooking process is also a tool node. A topic that only explains a process in natural language is served by a generative answers node. A Go to another topic node moves between topics; it cannot run a flow."},
"1007802": {"exam": "AB-620", "n": 42, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "The partner's capability is only available through a standardized agent-to-agent endpoint, so it is connected as an A2A integration by supplying that endpoint. It is not an indexed knowledge source, not an MCP tool, and generative responses cannot track shipments."},
"1007803": {"exam": "AB-620", "n": 43, "boxes": ["Add an external agent of type Microsoft Foundry.", "Enter the Foundry project endpoint URL to create the connection."], "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "A Foundry agent is connected from the Agents page by adding an external agent of type Microsoft Foundry; the connection is created from the Foundry project endpoint URL, which identifies the project and lets you pick the agent. Publishing the Copilot Studio agent or indexing Foundry output has nothing to do with delegation."},
"1007804": {"exam": "AB-620", "n": 44, "boxes": ["Share the component collection with teammates while controlling edit access.", "Create a component collection and move shared components into it.", "Restrict component collection to the primary agent."], "verdict": "confirmed", "confidence": "medium", "kp": "ALM & deployment", "why": "Component collections package topics, tools and other assets once so several agents reuse them without copies. Sharing the collection with view-only access for most builders and edit rights for the platform team limits who can change shared assets, and a collection can be kept for a single agent when it must not be reused elsewhere. Exporting and copying assets recreates the duplication problem."},
"1007805": {"exam": "AB-620", "n": 45, "answer": "CE", "verdict": "confirmed", "confidence": "high", "kp": "Prompts & generative answers", "why": "Prompt-driven summarization is built as a reusable custom prompt (template) applied wherever summaries are produced, and the model it runs on is selected from the Microsoft Foundry model catalog inside that prompt's configuration. Citations, grounding on Azure AI Search or publishing do not determine which model a prompt uses.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/bring-your-own-model-prompts"},
"1007806": {"exam": "AB-620", "n": 46, "boxes": ["Select the service principal as the authentication type.", "Enter the name of the Azure AI Search index.", "Provide the Azure AI Search Endpoint URL in the connection details."], "verdict": "corrected", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Adding Azure AI Search as knowledge creates a connection with an Authentication type (Access Key, Client Certificate, Service principal, or Microsoft Entra ID Integrated), the Azure AI Search Endpoint URL, and then the name of the vector index to use. A service principal satisfies the governed, non-shared-credential requirement, the index name selects the curated policy content, and the endpoint URL targets the right search service instance.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/knowledge-azure-ai-search"},
"1007807": {"exam": "AB-620", "n": 47, "boxes": ["Delegate the request to a data-access agent.", "Delegate the request to a knowledge-focused agent.", "Delegate the request to a tools-first agent."], "verdict": "corrected", "confidence": "high", "kp": "Multi-agent & MCP", "why": "In a multi-agent design each specialist does one job: structured, up-to-date metrics come from a data-access agent (such as a Fabric data agent), policy questions go to a knowledge-focused agent grounded on curated content, and authenticated updates are performed by a tools-first agent that calls connectors or MCP tools."},
"1007808": {"exam": "AB-620", "n": 48, "boxes": ["Add the connector as a tool in the agent.", "Create or reuse a connection for the connector.", "Map topic variables to the tool inputs.", "Parse the JSON response and assign it to a topic variable."], "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "The connector's actions become invocable once added as a tool; a connection created with the service account handles authentication at the service level instead of per user; topic variables mapped to the tool inputs pass conversation context; and the JSON response assigned to a topic variable can then be shown to the user."},
"1007809": {"exam": "AB-620", "n": 49, "boxes": ["Initiate the process to add a knowledge source to the agent.", "Create a new Azure AI Search connection.", "Configure the authentication method and provide the required connection details.", "Specify the Azure AI Search index to use for grounding.", "Associate the configured knowledge source with the agent."], "verdict": "confirmed", "confidence": "medium", "kp": "Knowledge sources & grounding", "why": "You start from Add knowledge, choose Azure AI Search and create a connection, supply the authentication method and endpoint details, then pick the index that grounds answers, and finally add the configured source to the agent. The index can only be chosen after the connection authenticates."},
"1007810": {"exam": "AB-620", "n": 50, "boxes": ["Publish the connected agent.", "Add the connected agent.", "Add the connected agent."], "verdict": "confirmed", "confidence": "medium", "kp": "Multi-agent & MCP", "why": "The documented prerequisites for connecting to an existing Copilot Studio agent are that it is in the same environment, is published, allows connections from other agents, and is owned by or shared with the maker; the main agent then adds it from the Agents page. So publishing is what makes it callable by other agents, and adding it as a connected agent is what lets the main agent collaborate with it and invoke it in conversations. No separate connection configuration step is documented, and indexing it as knowledge would make it content rather than a collaborator.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/add-agent-copilot-studio-agent"},
"1007811": {"exam": "AB-620", "n": 51, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Multi-agent & MCP", "why": "Agent-to-agent delegation through a standard interface is configured by giving the target agent's A2A endpoint information. A Fabric data agent is a different connector type, and documentation or an indexed knowledge source lets the agent talk about the other agent, not invoke it."},
"1007812": {"exam": "AB-620", "n": 52, "answer": "CE", "verdict": "confirmed", "confidence": "low", "kp": "Prompts & generative answers", "why": "Damaged copy of #2: the option that actually meets the requirement, selecting an approved model in the prompt's Model setting (from the Microsoft Foundry model catalog), is missing here. A prompt always runs on the model selected in that setting, so a line in the instructions cannot enforce an approved model, and in #2, #45 and #61, which offer the model selection, that line is a distractor. In this copy E (keep the reusable template applied) is clearly right and C is chosen only by elimination, because publishing, citations and Azure AI Search grounding never change the model. In the exam, pick the model-selection option whenever it is offered; fall back to the instruction line only when it is not.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/bring-your-own-model-prompts"},
"1007813": {"exam": "AB-620", "n": 53, "answer": "AC", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "Delegating to a Microsoft Foundry agent means adding an external agent and pointing the connection at the Foundry project endpoint URL, which identifies the project and agent. Publishing the Copilot Studio agent or adding knowledge is not part of the integration."},
"1007814": {"exam": "AB-620", "n": 54, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "MCP servers are integrated from the agent's Tools page: adding the server (with its authentication) exposes its published tools for the agent to call during conversations. Generative answers and knowledge sources do not invoke tools, and publishing changes nothing."},
"1007815": {"exam": "AB-620", "n": 55, "boxes": ["Power Platform connector tool.", "Power Platform connector as real-time knowledge.", "Power Platform connector as real-time knowledge."], "verdict": "corrected", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Updating a record is an action, so it needs the connector as a tool with an authenticated connection. Answering from live data, and doing so without copying anything into a search index, are both what a Power Platform connector used as real-time knowledge provides: it queries the system when asked. A Copilot connector knowledge source is the indexed option, the opposite of what the third requirement asks.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/knowledge-real-time-connectors"},
"1007816": {"exam": "AB-620", "n": 56, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "Governed analytical data is reached by connecting the Microsoft Fabric data agent as a connected agent; it answers structured questions while Fabric's security and scope controls apply. Direct REST calls or an indexed copy would bypass those controls, and a flow is not a data agent."},
"1007817": {"exam": "AB-620", "n": 57, "boxes": ["Copilot connector knowledge source", "Power Platform connector for real-time knowledge", "Power Platform connector tool"], "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Searchable answers over indexed content come from a Copilot connector knowledge source; up-to-date facts without indexing come from a Power Platform connector used as real-time knowledge; an authenticated update during the conversation is an action, so it is a Power Platform connector tool."},
"1007818": {"exam": "AB-620", "n": 58, "boxes": ["Add a Copilot connector knowledge source for indexed content.", "Connect to an MCP server and add its tools to the agent.", "Add a Power Platform connector tool and call it from a topic."], "verdict": "confirmed", "confidence": "medium", "kp": "Multi-agent & MCP", "why": "Grounded answers over enterprise content use a knowledge source (here the indexed Copilot connector); functions exposed through the standardized Model Context Protocol are reached by connecting the MCP server and adding its tools; writing an update with an authenticated action during the conversation is a Power Platform connector tool called from the topic."},
"1007819": {"exam": "AB-620", "n": 59, "boxes": ["Configure the Copilot connector in Microsoft 365 Admin Center.", "Call the connector knowledge source.", "Add the Copilot connector as a knowledge source."], "verdict": "corrected", "confidence": "medium", "kp": "Knowledge sources & grounding", "why": "Copilot (Microsoft Graph) connectors are set up by a tenant administrator in the Microsoft 365 admin center, which makes the indexed content available at tenant level. The builder adds that connector to the agent as a knowledge source, and at runtime the agent calls the knowledge source so answers are grounded in content the user is authorized to see. Nothing is created in the Power Platform admin center or directly in Copilot Studio.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/knowledge-copilot-studio"},
"1007820": {"exam": "AB-620", "n": 60, "boxes": ["Instruct the agent to cite sources in knowledge settings.", "Configure Azure AI Search as the grounding data source.", "Deploy a model in Foundry to an agent and connect to Copilot Studio."], "verdict": "confirmed", "confidence": "medium", "kp": "Prompts & generative answers", "why": "Traceability comes from citations in the knowledge settings; a centralized index is Azure AI Search configured as the grounding source; an enterprise-approved foundation model is one deployed in Microsoft Foundry and connected to Copilot Studio. Uploading documents into the agent would bypass the central index."},
"1007821": {"exam": "AB-620", "n": 61, "answer": "DE", "verdict": "confirmed", "confidence": "high", "kp": "Prompts & generative answers", "why": "A custom prompt template applied where the structured response is generated gives consistent tone and structure, and the Foundry model catalog selection in that prompt's configuration makes it run on the approved model. Publishing, grounding, citations or per-topic authoring do not control the model.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/bring-your-own-model-prompts"},
"1007822": {"exam": "AB-620", "n": 62, "boxes": ["CreateTicket, EscalateIncident, GetTicket, UpdateSLA", "API key header X-API-Key", "Server URL"], "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "When an MCP server is added, you choose which of its published tools the agent may call (the allowed operations), store the credential in the connection, here an API key header, so topic steps never embed secrets, and set the server URL that routes requests to the right backend."},
"1007823": {"exam": "AB-620", "n": 63, "answer": "BC", "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "Computer use lets the agent drive a desktop application's UI inside the platform-hosted execution environment, and the agent runtime (activity) view shows each automation step while a conversation runs. A knowledge source or a REST connector cannot operate a UI."},
"1007824": {"exam": "AB-620", "n": 64, "boxes": ["Make an HTTPS request.", "Add a standard connector.", "Trigger a notification."], "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "In an agent flow an external API is called with an HTTP request action, data in supported internal sources is read through the standard connector for that source, and a Teams message is sent with a notification action."},
"1007825": {"exam": "AB-620", "n": 65, "answer": "AC", "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "Two supported ways to call an authenticated REST API at runtime: an HTTP request action invoked from a topic, or the REST API added as a tool that a topic or the orchestrator calls. Knowledge sources, generative answers, formulas and redirects do not execute API calls."},
"1007826": {"exam": "AB-620", "n": 66, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "An authenticated MCP server is usable only after the connection the agent uses is configured with the required authentication. Generative answers, real-time knowledge or an indexed copy of its output cannot execute MCP tool calls."},
"1007827": {"exam": "AB-620", "n": 67, "boxes": ["Configure a REST action and call it from a topic.", "Build an authenticated connection for the API.", "Store the API response in a topic variable."], "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "The call itself is a REST action invoked from the topic; it runs with proper authentication through a connection built for the API; and the structured response is stored in a topic variable so later nodes can use it."},
"1007828": {"exam": "AB-620", "n": 68, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Prompts & generative answers", "why": "Requiring grounding means the generative answers node only responds when retrieval returns relevant content, so with Azure AI Search as the retrieval source the agent stops producing answers that are not based on indexed content. Citations, boosting or uploading documents do not stop ungrounded answers."},
"1007829": {"exam": "AB-620", "n": 69, "boxes": ["Add the REST API tool.", "Configure the API endpoint details.", "Configure authentication for the API.", "Test the API configuration."], "verdict": "corrected", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "The documented order is: add a new tool and select REST API, upload the OpenAPI specification and describe the API (the endpoint details), provide the authentication details, select the tools from the API, then review, publish, create the connection and test. Authentication cannot be configured before the tool and its endpoint exist.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/agent-extend-action-rest-api"},
"1007830": {"exam": "AB-620", "n": 70, "boxes": ["Enable Computer use tool for the agent.", "Use a platform-hosted execution environment.", "Monitor run details in the agent runtime view."], "verdict": "confirmed", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "Computer use is the tool that drives an application's UI; it runs in the platform-hosted execution environment; and run details are observed in the agent runtime view."},
"1007831": {"exam": "AB-620", "n": 71, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Prompts & generative answers", "why": "Prompt instructions cannot restrict connector access; connector security is enforced by connections, DLP and permissions. The solution also does nothing about the executive-summary format."},
"1007832": {"exam": "AB-620", "n": 72, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Prompts & generative answers", "why": "A custom prompt placed in the specific topic that instructs the model to respond in an executive-summary structure applies the format only there, keeps using the knowledge the topic is grounded on, and leaves connector security controls untouched."},
"1021110": {"exam": "AB-620", "n": 73, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "An existing MCP server is connected from the agent's Tools page (Add a tool > New tool > Model Context Protocol), where the onboarding wizard takes the server URL and its authentication (API key or OAuth 2.0) and the published tools become callable during conversations. Rebuilding the server as a custom connector is unnecessary, real-time knowledge only reads data, and generative answers cannot invoke tools.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/mcp-add-existing-server-to-agent"},
"1021111": {"exam": "AB-620", "n": 74, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "An external agent is connected over the Agent2Agent protocol: on the Agents page choose Add agent > A2A agent and enter the target agent's endpoint URL plus its authentication. A Power Platform connector tool calls APIs rather than delegating to an agent, and uploaded documentation or generative answers only let the agent talk about the other agent.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/add-agent-agent-to-agent"},
"1021112": {"exam": "AB-620", "n": 75, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "An external agent is connected over the Agent2Agent protocol: on the Agents page choose Add agent > A2A agent and enter the target agent's endpoint URL plus its authentication. Generative answers cannot call another agent, a connector tool calls APIs rather than delegating tasks, and an indexed knowledge source only retrieves content.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/add-agent-agent-to-agent"},
"1021113": {"exam": "AB-620", "n": 76, "boxes": ["Create a new agent flow.", "Define input values for the flow.", "Add the connector action and configure the connection.", "Define output values for the flow.", "Test the flow run."], "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "An agent can only call a flow that starts with the When an agent calls the flow trigger, where the input parameters it passes are defined, and ends with Respond to the agent, which returns the output values. So you create the flow, define its inputs on the trigger, add the connector action that queries the database, map the results into the outputs, and then test a run to validate it before the agent relies on it (the flow must also be published before it can be added as a tool).", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/flow-agent"},
"1021114": {"exam": "AB-620", "n": 77, "boxes": ["Publish the agent.", "Retrieve current agent configuration values.", "Implement the Microsoft 365 Agents SDK in the custom app by using the retrieved configuration.", "Validate the end-to-end conversation workflow in a test environment."], "verdict": "confirmed", "confidence": "high", "kp": "Channels & publishing", "why": "The stated dependencies fix the sequence: publish the agent, then retrieve its configuration (the Agents SDK connection string from the Web app or Native app channel, or the environment ID, tenant ID and schema name under Settings > Advanced > Metadata), implement the Copilot Studio client in the app with those values, and validate the end-to-end conversation before production. An Entra app registration with the CopilotStudio.Copilots.Invoke permission is a real prerequisite but usually already exists and is not one of the dependency-driven steps, and channel enablement is where the values are read rather than a separate step in this four-step sequence.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/publication-integrate-web-or-native-app-m365-agents-sdk"},
"1021115": {"exam": "AB-620", "n": 78, "boxes": ["Configure the content filtering level for AI-generated content.", "Review Azure Application Insights telemetry.", "Review conversation transcripts."], "verdict": "confirmed", "confidence": "high", "kp": "Responsible AI & content control", "why": "Copilot Studio checks both the user input and the generated response against content moderation, and the content moderation level sets how strictly unsafe output is blocked; disabling generative responses removes the feature instead of safeguarding it. A blocked answer raises a ContentFiltered error that you find in Application Insights telemetry (customEvents where customDimensions contains ContentFiltered), and the conversation transcripts show which user message triggered the filter. Region moves, trigger phrases, publishing history and connector run history have nothing to do with RAI filtering.", "ref": "https://learn.microsoft.com/en-us/troubleshoot/power-platform/copilot-studio/generative-answers/agent-response-filtered-by-responsible-ai"},
"1021116": {"exam": "AB-620", "n": 79, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "Because the MCP server requires authentication, its tools can be called only after the connection the agent uses is configured with the required API key or OAuth 2.0 settings in the MCP onboarding wizard. Default settings on publish do not authenticate anything, real-time knowledge does not execute tools, and generative answers cannot make MCP tool calls.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/mcp-add-existing-server-to-agent"},
"1021117": {"exam": "AB-620", "n": 80, "boxes": ["Delegate the request to a knowledge-focused agent.", "Delegate the request to a data-access agent.", "Delegate the request to a tools-first agent."], "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "Fabrikam's technical requirements isolate each specialist responsibility: policy Q&A is grounded in the indexed policy library (a knowledge-focused agent), metrics are delegated to the Fabric Data Agent over the semantic model (a data-access agent), and authenticated updates run through MCP server tools (a tools-first agent). Microsoft's guidance is to separate agents when a subtask has its own domain, tools or governance; putting all logic into one agent and its child agents is exactly what caused metric questions to be answered generatively instead of being routed.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/guidance/multi-agent-patterns"},
"1021118": {"exam": "AB-620", "n": 81, "boxes": ["Instruct the agent to cite sources in knowledge settings.", "Configure Azure AI Search as the grounding data source.", "Select a model from the Foundry model catalog."], "verdict": "confirmed", "confidence": "high", "kp": "Knowledge sources & grounding", "why": "Traceability means returning citations with grounded answers (for Azure AI Search, from a URL field such as metadata_storage_path in the index); the centralized vector index is reached by adding Azure AI Search as the knowledge (grounding) source; and an enterprise-approved model is chosen from the Microsoft Foundry model catalog. Uploading documents directly into the agent creates a separate copy instead of using the centralized index.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/knowledge-azure-ai-search"},
"1021119": {"exam": "AB-620", "n": 82, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "The case requires performance questions (backlog, SLA risk, parts shortages) to be delegated to a Fabric data agent that reads governed data through the Fabric semantic model, which is connected to Operations Concierge as an external agent. The Foundry agent is for summarization and classification, the MCP server is for authenticated transactional updates, and Azure AI Search serves policy Q&A.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/add-agent-fabric-data-agent"},
"1021120": {"exam": "AB-620", "n": 83, "answer": "AE", "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "To delegate IT requests to the existing Service Desk Agent, it must be connected as a Copilot Studio agent, which requires that agent to be published and to have \"Let other agents connect to and use this one\" turned on in its settings. Publishing the primary agent does not create a connection, replacing the agent with an MCP server reimplements its logic, and an indexed knowledge source cannot run its ticket creation.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/add-agent-copilot-studio-agent"},
"1021121": {"exam": "AB-620", "n": 84, "boxes": ["Select OAuth 2.0 as the authentication type for the MCP server.", "Select API key as the authentication type for the MCP server.", "Configure a server description about the MCP server role."], "verdict": "confirmed", "confidence": "high", "kp": "Multi-agent & MCP", "why": "The MCP onboarding wizard offers None, API key or OAuth 2.0 authentication. PartsOps needs per-user authentication so actions are traceable to the requester, which is OAuth 2.0 (each user signs in and consents); WarrantyRules uses a shared API key, so API key is selected. The orchestrator decides whether to call a server from its Server description, so a clear description of the server's role gives it that context; using the same authentication type for both servers contradicts their different requirements.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/mcp-add-existing-server-to-agent"},
"1007834": {"exam": "AB-620", "n": 85, "answer": "A", "verdict": "confirmed", "confidence": "low", "kp": "Prompts & generative answers", "why": "Configuring the custom prompt at the topic level scopes the executive-summary format to that topic and leaves other topics unchanged, while the topic continues to use its configured knowledge sources and the connector security controls. The alternative reading, that a separate prompt bypasses the generative answers node, is why some disagree."},
"1007835": {"exam": "AB-620", "n": 86, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "Repeatable evaluation needs a test set: predefined prompts with the expected responses, run the same way each time. Analytics, production scores and extra channels measure live traffic, which changes from run to run."},
"1007836": {"exam": "AB-620", "n": 87, "boxes": ["Configure stage access for the production stage.", "Use environment variables in the solution.", "Deploy the solution as managed."], "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Pipeline stage access restricts who can deploy to production; environment variables let one solution carry environment-specific values without editing components; deploying as managed gives production a locked-down solution whose components cannot be modified."},
"1007837": {"exam": "AB-620", "n": 88, "boxes": ["Pass or fail status", "Consistent outcomes", "Expected and generated responses"], "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "A case reported as meeting or missing the expectation is a pass/fail status; cases that fail in every run show consistent (not intermittent) outcomes; showing both the expected and the generated response is what each run reports. None of that proves production readiness or a root cause."},
"1007838": {"exam": "AB-620", "n": 89, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "Three interactions failing consistently while everything else passes pinpoints the part of the agent's scope that needs fixing. It does not prove the model is at fault, nor that the whole design is flawed or the agent undeployable."},
"1007839": {"exam": "AB-620", "n": 90, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "The supported way to move an agent is solution-based: add the existing agent to a custom solution, export it and import it in the target environment. Channels are not a transport mechanism, and duplicating or stripping components defeats ALM."},
"1007840": {"exam": "AB-620", "n": 91, "boxes": ["Secret environment variable", "Managed environment variable", "String environment variable"], "verdict": "confirmed", "confidence": "medium", "kp": "ALM & deployment", "why": "A secret environment variable is resolved at runtime from Key Vault, so a changed secret applies without republishing; an environment variable managed outside Copilot Studio can be confirmed by a builder but not changed there; an ordinary string environment variable carries a non-secret value that the published agent uses.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/authoring-variables-about"},
"1007841": {"exam": "AB-620", "n": 92, "boxes": ["Use a curated prompt list.", "Compare against predefined expected outcomes.", "Use a consistent scoring evaluation matrix."], "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "A fixed set of prepared interactions is a curated prompt list; a baseline means comparing responses with predefined expected outcomes; repeatable comparison across runs needs the same scoring matrix every time. Live traffic, impressions and feedback are not repeatable."},
"1007842": {"exam": "AB-620", "n": 93, "answer": "CDF", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "ALM-friendly configuration stores external references as environment variables so the agent definition stays identical across environments; builders treat them as read-only in Copilot Studio and administrators change values in the maker portal; and after a non-secret value changes, agents that use it are republished so the new value takes effect (only secret values are fetched at runtime). Hard-coding or assuming instant updates breaks that model.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/authoring-variables-about"},
"1007843": {"exam": "AB-620", "n": 94, "boxes": ["Unmanaged solution", "Managed solution", "Managed solution"], "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Development continues in an unmanaged solution; production imports a managed solution, which blocks direct modification and is the deployment-ready form exported from development."},
"1007844": {"exam": "AB-620", "n": 95, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "An ALM-ready container is a custom solution created from the Solutions area, into which the agents and their dependencies are added. Exporting as managed comes later; channels and direct agent export are not ALM mechanisms."},
"1007845": {"exam": "AB-620", "n": 96, "boxes": ["A pattern of failure across repeated runs.", "The response partially matches the expected answer.", "The specific underlying cause of the failure."], "verdict": "corrected", "confidence": "medium", "kp": "Testing, evaluation & analytics", "why": "The same interaction failing three times is a recurring pattern; the reasoning text about a partial match is the quality information; and what the evaluation cannot tell you, its limitation, is the specific root cause of the failure. The knowledge source used is reported, so it is not a limitation.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-agent-evaluation-results"},
"1007846": {"exam": "AB-620", "n": 97, "boxes": ["Enable pipelines for the tenant.", "Assign environments to pipeline stages.", "Trigger a pipeline run.", "Review deployment results."], "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Power Platform pipelines must first be enabled (the pipelines host and app), then development, test and production environments are linked to the pipeline's stages, after which a maker triggers a run from the source environment and the results of each stage deployment are reviewed."},
"1007847": {"exam": "AB-620", "n": 98, "answer": "CE", "verdict": "corrected", "confidence": "high", "kp": "Tools, connectors & HTTP", "why": "Computer use is the tool that lets an agent drive a legacy desktop application through its UI with a virtual mouse and keyboard. While testing it, the test experience shows the step-by-step reasoning on the left and a live preview of the actions on the machine on the right, and in conversations the tool shares reasoning and screenshots, which is how execution is inspected. A desktop flow or a custom connector is a different mechanism, and publishing does not create the execution environment.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/computer-use"},
"1007848": {"exam": "AB-620", "n": 99, "boxes": ["Export as a component collection.", "Use connection references and environment variables.", "Use an ALM pipeline."], "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Authored topics and prompts are shared across environments as a component collection; environment-specific connections and secrets travel through connection references and environment variables instead of hard-coded values; multi-stage deployments with approvals are automated with a Power Platform pipeline."},
"1007849": {"exam": "AB-620", "n": 100, "answer": "AE", "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Intermittent flow results are diagnosed from the flow's run history, where each run is listed, and from the details of the failed runs, which show every action's inputs, outputs and errors. The Activity tab has no error column, analytics are aggregated, and changing the trigger or timeout is a fix attempted before any diagnosis."},
"1007850": {"exam": "AB-620", "n": 101, "answer": "CD", "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "The case passed with a high score because the evaluation compares meaning, not exact wording, so the result is accepted as is; the only sensible follow-up is to confirm the knowledge source the answer came from keeps working. Rerunning for a score below 1.00, rewriting the test to force an exact match or investigating tools that were never invoked would be wasted effort."},
"1007851": {"exam": "AB-620", "n": 102, "boxes": ["Sequential stage progression", "Deployment input validation", "Centralized pipeline configuration"], "verdict": "corrected", "confidence": "high", "kp": "ALM & deployment", "why": "Pipelines move the same solution artifact through their stages in sequential order (it cannot skip QA); connections and environment variables are provided upfront and validated before the deployment begins, so missing connection references or variables are caught; and admins centrally manage and govern pipelines, stages and security for all linked environments from the pipelines host.", "ref": "https://learn.microsoft.com/en-us/power-platform/alm/pipelines"},
"1007852": {"exam": "AB-620", "n": 103, "boxes": ["Identify the high-value conversational intents the agent must handle.", "Author representative user prompts that trigger the identified intents.", "Define the expected outcomes and success criteria for each interaction.", "Baseline the test set to ensure deterministic evaluation across repeated runs."], "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "A meaningful test set starts from the intents that matter most, then representative prompts for them, then the expected outcome and success criteria for each prompt, and finally a baseline run that fixes the set so later runs are compared deterministically."},
"1007853": {"exam": "AB-620", "n": 104, "boxes": ["Execute the evaluation on demand.", "Compare responses against defined expectations.", "Use a curated prompt list as the interaction source."], "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "Team-controlled timing means running the evaluation on demand; acceptance criteria are implemented by comparing responses with the defined expected outcomes; consistency across runs comes from a curated prompt list as the fixed interaction source rather than live traffic or analytics."},
"1007854": {"exam": "AB-620", "n": 105, "boxes": ["Pass or fail status", "Consistent outcomes", "Expected and generated responses"], "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "Each case meeting or missing its expected response is a pass/fail status; the same cases failing in every run means the outcomes are consistent rather than intermittent; and the output shows the expected and the generated response side by side, not a root cause or a deployment decision."},
"1007855": {"exam": "AB-620", "n": 106, "boxes": ["Create or identify the Application Insights destination for telemetry.", "Configure which monitoring destination the agent uses.", "Enable monitoring for the agent.", "Publish the agent so the monitoring configuration takes effect."], "verdict": "confirmed", "confidence": "medium", "kp": "Testing, evaluation & analytics", "why": "You need an Application Insights resource first, then in the agent's Application Insights settings you point the agent at that resource (connection string) and switch on the activity and error logging, and the setting only reaches the running agent after it is republished. The generative-answer and model-catalog features are unrelated distractors."},
"1007856": {"exam": "AB-620", "n": 107, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Solutions are the ALM container for agents: creating a custom solution and adding the agent to it is exactly how agents are exported, imported and managed between environments."},
"1007857": {"exam": "AB-620", "n": 108, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Channels publish an agent to users; they are not a container that transports agents between environments. Solutions are."},
"1007858": {"exam": "AB-620", "n": 109, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Environment variables are read-only inside Copilot Studio; their values are managed in the Power Apps maker portal or during solution import by administrators, which is what keeps configuration separate from the agent definition."},
"1021122": {"exam": "AB-620", "n": 110, "answer": "BD", "verdict": "confirmed", "confidence": "high", "kp": "Agent flows", "why": "Configuring run after on the notification action to fire when the connector action has failed or has timed out handles those outcomes explicitly and lets the flow continue, and grouping the related actions in a scope gives a try-catch structure for handling the failure as a unit. A longer timeout and concurrency control on apply to each do not handle failures at all.", "ref": "https://learn.microsoft.com/en-us/power-automate/guidance/coding-guidelines/error-handling"},
"1021123": {"exam": "AB-620", "n": 111, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "For an agent built in Copilot Studio in Teams, the supported way to move it without rebuilding is to export it from the source team and import it into the target team with the Power Apps Teams app (Dataverse for Teams customizations). Removing agent components directly from a solution makes export and import fail, pipelines deploy solutions rather than discovering loose agents, and recreating changes by hand defeats ALM.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/authoring-solutions-import-export"},
"1021124": {"exam": "AB-620", "n": 112, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Testing, evaluation & analytics", "why": "A standardized evaluation set of fixed prepared interactions with expected responses, run the same way each time, is the only option that compares answers against a baseline and allows consistent comparison across runs, which is what agent evaluation test sets do. Manual transcript review, abandonment rates on the Analytics dashboard and pilot CSAT or containment metrics come from live, varying traffic and have no predefined baseline.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-agent-evaluation-intro"},
"1021125": {"exam": "AB-620", "n": 113, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "Agent evaluation runs a fixed test set of prompts with expected responses, scores each answer against them and, because the same test set can be rerun after every change, gives an objective comparison with earlier runs. The test pane is manual and hard to repeat, channel usage metrics say nothing about accuracy, and keyword searches of transcripts do not measure answers against a golden response.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-agent-evaluation-intro"},
"1021126": {"exam": "AB-620", "n": 114, "boxes": ["Open the Solutions area in Copilot Studio.", "Define the solution name and publisher.", "Save the solution container."], "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "In Copilot Studio you open the solution explorer (… > Solutions), select New solution and enter the display name, name and publisher (whose prefix is applied to components), then create/save it. The new solution then opens automatically, so reviewing its details page is not a step needed to create the container that agents and assets are added to.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/authoring-solutions-overview"},
"1021127": {"exam": "AB-620", "n": 115, "boxes": ["Execute the evaluation on demand.", "Compare responses against defined expectations.", "Use a curated prompt list as the interaction source."], "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "Team-controlled timing means running the evaluation on demand rather than on a schedule; acceptance criteria are applied by comparing each response with the expected response defined in the test case; and consistency across runs comes from a fixed test set (a curated prompt list) rather than live user conversations, which change from run to run. Copilot Studio agent evaluation works exactly this way: rerunning the same test set gives an objective standard to compare changes.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-agent-evaluation-intro"},
"1021128": {"exam": "AB-620", "n": 116, "boxes": ["Define the success criteria and evaluation objectives.", "Select the evaluation method and metrics aligned to the criteria.", "Collect agent interaction data and evaluation signals.", "Review evaluation results and identify improvement opportunities."], "verdict": "confirmed", "confidence": "high", "kp": "Testing, evaluation & analytics", "why": "Microsoft's evaluation guidance starts by defining what success looks like, which then drives the choice of test methods and metrics. Only then do you run the evaluation to collect the agent's responses and scores, and finally review the results to find and fix weaknesses before widening access. Collecting data before the criteria and methods are set produces signals you can't judge against anything.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-agent-evaluation-intro"},
"984433": {"exam": "AB-100", "n": 1, "boxes": ["Microsoft Power Platform Well-Architected framework", "Success by Design"], "verdict": "corrected", "confidence": "low", "kp": "Frameworks & methodologies", "why": "Microsoft's design guidance for Copilot Studio agents (security, reliability, telemetry, compliant deployment checklists) lives in the Power Platform Well-Architected framework and its intelligent-application workload, which is what the case study's compliance checklist and telemetry requirements point to. Success by Design is the FastTrack implementation methodology for Dynamics 365 and Power Platform solutions, with prescriptive guidance for conversational experiences and adoption. The ALM Accelerator is a deployment tool, not a best-practice framework, and the Cloud Adoption Framework covers Azure infrastructure."},
"984434": {"exam": "AB-100", "n": 2, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Frameworks & methodologies", "why": "The Microsoft Cloud Adoption Framework for Azure is the methodology for migrating on-premises infrastructure to Azure: strategy, plan, landing zones, migrate, govern and manage. Success by Design is for Dynamics 365 and Power Platform implementations, and the CoE kit and project setup wizard are Power Platform tooling."},
"984435": {"exam": "AB-100", "n": 3, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Business terms let Copilot understand custom terminology; mapping the existing display names of the Lead table's columns as business terms covers every field with the least effort, because the display names already carry the business meaning. Schema names are technical, creating a term per field is more work, and merging fields destroys the data model."},
"984436": {"exam": "AB-100", "n": 4, "boxes": ["Natural language understanding (NLU)", "Natural language understanding + (NLU+)"], "verdict": "confirmed", "confidence": "medium", "kp": "Copilot Studio agent design", "why": "Copilot Studio's standard models are NLU and NLU+. The classic NLU model handles short, simple trigger phrases for topic matching without generative orchestration, which fits Agent1. NLU+ is the standard model that supports the Dynamics 365 Contact Center voice channel, which Agent2 needs. CLU is a custom Azure Language model (not a standard model), and Azure OpenAI is not a topic-matching model."},
"984437": {"exam": "AB-100", "n": 5, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Copilot in-app help for finance and operations apps can be extended with uploaded files (PDF, Word, RTF) as knowledge without authoring topics; any other source type, such as SharePoint or search indexes, requires adding your own topic to the finance and operations Copilot agent in Copilot Studio."},
"984438": {"exam": "AB-100", "n": 6, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Microsoft 365 Copilot extensibility", "why": "External logic hosted in Azure (Functions, Logic Apps, REST APIs) is exposed to Microsoft 365 Copilot and to Copilot Studio agents through a Power Platform connector, which Copilot can then invoke as an action. Skills are the retired Bot Framework mechanism, and a custom engine agent replaces Copilot's orchestration rather than extending it with external logic."},
"984439": {"exam": "AB-100", "n": 7, "boxes": ["Define standardized prompt templates.", "Store prompts in a Git repository."], "verdict": "confirmed", "confidence": "high", "kp": "Prompt engineering & evaluation", "why": "Consistent responses across business units come from standardized, reusable prompt templates; governance and version control come from keeping the prompts in a Git repository with history, branching and reviews, which also costs little to run."},
"984440": {"exam": "AB-100", "n": 8, "boxes": ["Move to a multi-agent architecture.", "Add a grounding data source."], "verdict": "confirmed", "confidence": "high", "kp": "Agent architecture & orchestration", "why": "One agent with one prompt doing a chain of tasks is slow and leaves work incomplete; splitting the tasks across specialized agents improves performance and completeness. Weak domain-specific reasoning is an accuracy problem that grounding on authoritative domain data fixes; a larger model or a connector does not supply the missing knowledge."},
"984441": {"exam": "AB-100", "n": 9, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Agent types & use cases", "why": "A task agent automates the bounded review step, scoring transaction histories for fraud risk, while the human analyst keeps the final decision, which the requirement demands. An autonomous agent that closes cases removes the human, Word Copilot does not review transactions, and Power BI exports are analytics, not automation."},
"984442": {"exam": "AB-100", "n": 10, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Azure AI Search indexes heterogeneous content (SQL data, files, API and log output) into one searchable, vectorized index that Copilot Studio can use as a knowledge source. Data Lake and Cosmos DB store data but are not knowledge sources, and Translator is unrelated."},
"984443": {"exam": "AB-100", "n": 11, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "A single catalog in Dataverse gives both the Commerce agent and the Power Apps inventory agent one governed source of truth with native connectors. Per-agent tables, scraped SharePoint content or vendor PDFs create drift and inconsistent attributes."},
"984444": {"exam": "AB-100", "n": 12, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "A horizon-based framework (horizons 1, 2 and 3) evaluates a portfolio of initiatives at different maturity levels, weighing near-term returns against capability building and long-term strategic innovation. Cost-benefit, IRR and prioritization grids each capture only one dimension."},
"984445": {"exam": "AB-100", "n": 13, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Dataverse consolidates data into governed tables, carries built-in security roles, data classification and DLP policies, and serves Copilot Studio, Dynamics 365 and external models for both grounding and analytics. Data Lake, Cosmos DB and Power BI semantic models lack that combination."},
"984446": {"exam": "AB-100", "n": 14, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "An accurate return-on-AI-investment analysis starts from the full cost base: development, deployment and operating costs, compared with the cost of the current process. Metrics, benchmarking and experience modelling come after the baseline is known."},
"994132": {"exam": "AB-100", "n": 15, "boxes": ["Integration", "User acceptance"], "verdict": "confirmed", "confidence": "high", "kp": "Testing & quality", "why": "Data exchange between Dynamics 365 Sales and Finance is verified by integration testing; alignment with defined user workflows and business processes is verified by user acceptance testing. Performance, exploratory and drift testing measure other things."},
"994133": {"exam": "AB-100", "n": 16, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Governance, security & compliance", "why": "An agent in a Canadian environment calling an Azure OpenAI connector in the United States moves data across regions, which is only allowed when cross-region data movement is enabled for the environment and its connector dependencies. Moving the tenant or storing data in the US does not satisfy residency policy, and DLP settings govern connectors, not regions."},
"994134": {"exam": "AB-100", "n": 17, "boxes": ["Rewrite the prompt with clear and task-specific instructions.", "Use responses with only reference sources and limit the response scope."], "verdict": "confirmed", "confidence": "high", "kp": "Prompt engineering & evaluation", "why": "A vague instruction like \"help as best you can\" produces inconsistent behaviour, so it is rewritten with clear, task-specific instructions. A retrieval prompt stays accurate when answers are restricted to the referenced knowledge and the scope is limited; removing the source or adding open-ended questions invites ungrounded answers."},
"994135": {"exam": "AB-100", "n": 18, "boxes": ["Use prompts that have varied phrasing.", "Response relevance and accuracy"], "verdict": "confirmed", "confidence": "high", "kp": "Prompt engineering & evaluation", "why": "Validating prompts means testing the same intents with varied phrasing to prove the agent responds consistently, and measuring whether the responses are relevant and accurate. Word counts and generation time say nothing about correctness."},
"994136": {"exam": "AB-100", "n": 19, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Production receives a managed solution: exporting the Dev1 solution as managed and importing it into Prod1 deploys the agent with locked components and the least ongoing effort. Sharing does not cross environments, unmanaged imports are for development, and rebuilding is manual work."},
"994137": {"exam": "AB-100", "n": 20, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Irrelevant or inaccurate grounded answers usually come from poor data: incomplete, duplicated or inconsistent Dataverse records. Cleansing the data fixes the source; retraining, training examples or adaptive cards do not improve grounding quality."},
"994138": {"exam": "AB-100", "n": 21, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Customer data spread across ServiceNow, Dynamics 365 Finance and Supply Chain Management and SharePoint files is reached with Power Platform connectors, which give the agent governed, real-time access to each system. A model router, prompts or search indexing settings do not connect the systems."},
"994139": {"exam": "AB-100", "n": 22, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "A return-on-AI-investment analysis is the framework that brings together total cost of ownership, expected savings from automation and the build-versus-extend decision; a break-even analysis alone, prebuilt agents or custom model training do not evaluate the financial implications."},
"994140": {"exam": "AB-100", "n": 23, "answer": "C", "verdict": "confirmed", "confidence": "medium", "kp": "Data preparation & grounding", "why": "The subset of corporate data already lives in the Power BI semantic model over Dataverse; endorsing (promoting or certifying) the model marks it as trusted and ready for AI experiences such as Copilot to ground on. Sharing the workspace or exporting the model does not prepare it, and Dataverse tables are already populated."},
"994141": {"exam": "AB-100", "n": 24, "boxes": ["Autonomous", "Task"], "verdict": "corrected", "confidence": "high", "kp": "Agent types & use cases", "why": "Orchestrating order fulfillment and shipping end to end, reacting to events and acting across systems without a user in the loop, is an autonomous agent. Analysing historical data to replenish stock is a bounded, well-defined piece of work, which is a task agent; a prompt-and-response agent only answers questions."},
"994142": {"exam": "AB-100", "n": 25, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Data that feeds sentiment reports must be representative, so preparing it means identifying and addressing biased data. Sorting by name, building a flow or an agent flow does nothing for data quality."},
"994143": {"exam": "AB-100", "n": 26, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "The Business value toolkit captures a Power Platform solution's metadata and telemetry and turns them into a value and return-on-investment model. The admin center manages environments, Success by Design is a methodology, and the Cloud Adoption Framework targets Azure."},
"994144": {"exam": "AB-100", "n": 27, "boxes": ["Microsoft Foundry", "Microsoft Copilot Studio"], "verdict": "corrected", "confidence": "medium", "kp": "Agent architecture & orchestration", "why": "An agent that is extended in code with Semantic Kernel and connects to many business apps and APIs is built in Microsoft Foundry, the pro-code platform. An agent that connects directly to Dataverse and is embedded in a Power Apps canvas app is built in Copilot Studio, whose agents are added to canvas apps as a control. Copilot in Power Apps is the maker assistant for building apps, not an agent, and Logic Apps is workflow automation."},
"994145": {"exam": "AB-100", "n": 28, "answer": "C", "verdict": "confirmed", "confidence": "medium", "kp": "ROI & business value", "why": "Evaluating the potential cost of a solution that does not exist yet is an estimate, which is what the Total Cost of Ownership Calculator (or the Azure pricing calculator) produces for a return-on-AI-investment analysis. Cost Management + Billing reports actual spend on running resources, the Fabric SKU estimator only sizes Fabric capacity, and reservations are a discount mechanism."},
"994146": {"exam": "AB-100", "n": 29, "boxes": ["An Microsoft Foundry hub", "An AI Builder prebuilt prompt"], "verdict": "corrected", "confidence": "low", "kp": "Agent architecture & orchestration", "why": "A Microsoft Foundry hub is the centralized workspace that governs models, connections and projects for a team, so it is the component for managing AI models in one place. Generating short overviews from unstructured text without training or code is the AI Builder prebuilt summarize-text prompt, used directly in Power Automate; a prebuilt model is for structured tasks such as invoice or receipt processing.", "ref": "https://learn.microsoft.com/en-us/azure/foundry-classic/concepts/ai-resources"},
"994147": {"exam": "AB-100", "n": 30, "boxes": ["AI Summaries with Copilot", "Collections coordinator summary"], "verdict": "corrected", "confidence": "medium", "kp": "Dynamics 365 Copilot features", "why": "In Dynamics 365 Finance, AI summaries with Copilot on vendor pages surface the key facts about a vendor, including overdue invoices and outstanding balances, for accounts payable staff. For customer debt recovery, the collections coordinator summary condenses overdue invoices and payment history so reviews take less time. The Account Reconciliation agent matches bank statements, and the Supplier Communications agent handles purchase-order follow-ups with vendors.", "ref": "https://learn.microsoft.com/en-us/dynamics365/release-plan/2024wave1/finance-supply-chain/dynamics365-supply-chain-management/view-context-aware-vendor-summaries-copilot"},
"994148": {"exam": "AB-100", "n": 31, "answer": "AC", "verdict": "confirmed", "confidence": "medium", "kp": "ROI & business value", "why": "The CFO's quarterly analysis uses the Copilot Studio agent usage estimator, which prices an agent from its design: the orchestration method (classic or generative) changes how many model calls each conversation makes, and the generative models used (standard versus deep-reasoning) are billed at different credit rates. Message length and session duration are symptoms of usage, not design components the estimator evaluates."},
"994149": {"exam": "AB-100", "n": 32, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "The custom agent must select topics by a description of their purpose rather than trigger phrases, connect to other agents chosen by description, and call business logic held outside the application: all of that is what generative orchestration provides. Classic orchestration relies on trigger phrases, and evaluators or reasoning models do not route topics."},
"999649": {"exam": "AB-100", "n": 33, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Customer feedback used for sentiment reports must be representative, so preparing it means identifying and addressing biased data. Database size, language and sort order do not make the data clean or suitable."},
"999650": {"exam": "AB-100", "n": 34, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "Estimating the potential cost of an Azure solution before it exists is what the Azure pricing calculator is for; it models the services and usage to project spend for the return-on-AI-investment analysis. The TCO calculator compares on-premises with Azure, reservations are a discount mechanism, and Azure Monitor observes running resources."},
"999651": {"exam": "AB-100", "n": 35, "answer": "C", "verdict": "confirmed", "confidence": "medium", "kp": "ROI & business value", "why": "Of these options only Cost Management + Billing deals with Azure costs: it forecasts and breaks down spend by resource and business unit, which feeds the return-on-AI-investment analysis. Savings plans are a commitment discount, the Fabric SKU estimator sizes Fabric capacity only, and Azure Monitor collects telemetry, not cost."},
"999652": {"exam": "AB-100", "n": 36, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "The Azure pricing calculator projects what the planned services will cost, which is the input a return-on-AI-investment analysis needs before deployment. Reservations and anomaly detection manage existing spend, and the Fabric SKU estimator only sizes Fabric capacity."},
"1012337": {"exam": "AB-100", "n": 37, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "The Azure pricing calculator estimates the cost of planned Azure services from expected usage, which is exactly the potential-cost figure a return-on-AI-investment analysis starts from. Anomaly detection and savings plans apply to running workloads, and the Fabric SKU estimator is specific to Fabric."},
"1012338": {"exam": "AB-100", "n": 38, "answer": "D", "verdict": "confirmed", "confidence": "medium", "kp": "ROI & business value", "why": "Among these options only Cost Management + Billing evaluates Azure costs: forecasts, budgets and cost breakdowns per business unit that support the return-on-AI-investment analysis. Savings plans discount committed usage, anomaly detection flags unusual spend, and Azure Monitor is telemetry."},
"1012339": {"exam": "AB-100", "n": 39, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Clean, suitable data means finding and fixing missing or inconsistent records before the agent ingests them; sort order and database size are irrelevant, and privacy compliance protects the data rather than cleaning it."},
"1012340": {"exam": "AB-100", "n": 40, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Copilot Studio connects natively to Application Insights, which captures telemetry for every agent across channels (events, messages, errors, performance) and gives comprehensive performance insight. Azure DevOps is for delivery pipelines, Power BI only visualizes, and Customer Voice collects survey feedback."},
"1012341": {"exam": "AB-100", "n": 41, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Monitoring & analytics", "why": "Without Application Insights among the options, the Analytics (Monitor) area in Copilot Studio is the one that provides agent telemetry and performance insights: sessions, engagement, resolution, escalation and topic performance across channels. Purview audits governance and compliance, Power BI visualizes data, and Customer Voice gathers surveys."},
"1012342": {"exam": "AB-100", "n": 42, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Application Insights is the telemetry destination Copilot Studio integrates with, giving per-agent events, errors and performance across channels. Log Analytics only stores and queries what Application Insights sends, Azure Advisor gives resource recommendations, and Customer Voice collects feedback."},
"1012343": {"exam": "AB-100", "n": 43, "answer": "C", "verdict": "confirmed", "confidence": "low", "kp": "Monitoring & analytics", "why": "The agents' Application Insights telemetry lands in a Log Analytics workspace, where it can be queried and monitored across every agent and channel, so of these options Log Analytics is the comprehensive telemetry store. The Analytics area in Copilot Studio gives built-in performance insights per agent but no raw telemetry; Azure Advisor and Purview do not monitor agents."},
"1012344": {"exam": "AB-100", "n": 44, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Data preparation & grounding", "why": "Sentiment reports are only reliable when the feedback data is representative, so identifying and addressing biased data is the preparation step. Size limits, translation and compliance checks do not make the data suitable for analysis."},
"1021234": {"exam": "AB-100", "n": 45, "boxes": ["Time-based", "Ongoing operations"], "verdict": "confirmed", "confidence": "medium", "kp": "ROI & business value", "why": "Early indicators of value are time-based measures such as time saved per task, time to value and payback period, which show whether the solution is on track long before financial results (cost savings, revenue) or strategic value (differentiation, new business models) can be confirmed. A complete accounting of lifecycle costs has to include ongoing operations: monitoring and evaluation, retraining, prompt maintenance, support, licensing and consumption that keep accruing after go-live. Infrastructure and data quality and preparation are real cost drivers, but they are largely up-front and do not by themselves cover the full lifecycle.", "ref": "https://learn.microsoft.com/en-us/training/modules/evaluate-costs-benefits-ai-powered-business-solution/2-roi-criteria-ai-powered-business-solution-including-total-cost-ownership"},
"1021235": {"exam": "AB-100", "n": 46, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Frameworks & methodologies", "why": "The Cloud Adoption Framework for Azure defines the AI adoption process (strategy, plan, ready, then govern, secure and manage), which sets standards for managing, securing and governing AI workloads. The Power Platform CoE kit is governance tooling for Power Platform, Success by Design is the Dynamics 365 implementation methodology, and Foundry Control Plane is an operational console for agents, not an adoption process.", "ref": "https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ai/strategy"},
"984447": {"exam": "AB-100", "n": 47, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "The sales executives interact hands-free through headsets, so the agent needs the Voice template in Copilot Studio, which also satisfies the low-code and Dataverse requirements. Foundry templates are code-first, and an IT helpdesk template targets a different scenario."},
"984448": {"exam": "AB-100", "n": 48, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Faster prospect correspondence from Dynamics 365 Sales is what Copilot email assist does: it drafts and suggests follow-up emails from the opportunity context. Azure AI Search, a voice agent and Deep Research do not write customer emails."},
"984449": {"exam": "AB-100", "n": 49, "boxes": ["Microsoft Copilot Studio", "a Fallback topic"], "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "The case study requires a low-code agent with Dataverse at its core, which is built in Copilot Studio. Unexpected agent behaviour, such as failing to answer, is handled in the Fallback system topic, where after two failed attempts the conversation is escalated to a live representative."},
"984450": {"exam": "AB-100", "n": 50, "answer": "D", "verdict": "confirmed", "confidence": "medium", "kp": "Microsoft 365 Copilot extensibility", "why": "Microsoft 365 Copilot reaches SharePoint and Teams content through Microsoft Graph, which also enforces the user's permissions so responses are contextually relevant; configuring Graph access (including which sites are in scope) is the design element. Desktop flows, custom crawlers or generic SharePoint settings do not feed Copilot."},
"984451": {"exam": "AB-100", "n": 51, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "The accounts payable Copilot capabilities ship inside Dynamics 365 Finance; the prerequisite is to grant users the Finance and Operations AI security role so the prebuilt features are available to them. Nothing has to be built in Copilot Studio or Foundry, and Copilot for Sales is unrelated."},
"984452": {"exam": "AB-100", "n": 52, "answer": "BE", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "A Contact Center agent is built in Copilot Studio, and handing a conversation to a live representative requires the customer engagement hub (Dynamics 365 Customer Service / Contact Center) where human agents receive the transfer. Foundry, the Agents Toolkit and Bot Service skills are not part of the hand-off."},
"984453": {"exam": "AB-100", "n": 53, "boxes": ["AI Summaries with Copilot", "Generative insights for Demand planning"], "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "In Supply Chain Management, AI summaries with Copilot surface the key information on records such as customer orders for managers, and generative insights in Demand planning help planners forecast future product needs."},
"984454": {"exam": "AB-100", "n": 54, "boxes": ["From Copilot Studio, add SharePoint as a knowledge source.", "From Copilot Studio, configure the SharePoint tool."], "verdict": "confirmed", "confidence": "low", "kp": "Data preparation & grounding", "why": "Answering policy questions over 10,000 PDFs is done by adding the SharePoint library as a knowledge source, which indexes the documents with the users' permissions. The Department column is library metadata that generative answers do not read, so relating departments to policies needs the SharePoint connector configured as a tool, which can query the library's items and columns. Sensitivity labels, SharePoint Premium or a copied Dataverse table do not expose that relationship from the library itself."},
"984455": {"exam": "AB-100", "n": 55, "boxes": ["Copilot Studio voice features", "A deep reasoning model"], "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "Interactive spoken responses are a built-in Copilot Studio voice capability, and better decision-making and accuracy on complex questions comes from enabling a deep reasoning model for the agent. Azure AI Speech, SSML and the Language service are lower-level Azure services rather than Copilot Studio design choices."},
"984456": {"exam": "AB-100", "n": 56, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "Computer use lets a Copilot Studio agent operate websites and apps like a person, clicking, typing and reading the screen, which is what simulating user interactions across third-party apps requires. MCP exposes tools, NLU+ is a language model, and skills are retired Bot Framework components."},
"984457": {"exam": "AB-100", "n": 57, "answer": "E", "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "Hand-off to a live representative in a Dynamics 365 Contact Center chat channel is configured in the Escalate system topic with a transfer conversation node, which triggers when the customer asks for a person. Flows, connectors, skills or the Conversation Start topic do not transfer the conversation."},
"984458": {"exam": "AB-100", "n": 58, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Agent architecture & orchestration", "why": "Extracting order details from files, writing to a database, updating status and sending confirmation emails are all connector-based steps that Power Automate flows do with no code, orchestrated by a Copilot Studio agent. Logic Apps, Semantic Kernel or Foundry multi-agent solutions require far more development effort."},
"984459": {"exam": "AB-100", "n": 59, "boxes": ["Must be uploaded to the agent", "Must be disabled for the agent"], "verdict": "corrected", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Custom knowledge for the finance and operations in-app help agent is added by uploading files to the Copilot for finance and operations apps agent in Copilot Studio. AI general knowledge is disabled by default, and Microsoft warns that enabling it increases the risk that answers include incorrect content, so to minimize inaccurate responses it stays disabled.", "ref": "https://learn.microsoft.com/en-us/dynamics365/fin-ops-core/dev-itpro/copilot/extend-copilot-generative-help"},
"984460": {"exam": "AB-100", "n": 60, "boxes": ["Conversation topics", "Microsoft Power Automate cloud flow"], "verdict": "confirmed", "confidence": "medium", "kp": "Agent architecture & orchestration", "why": "The rules and constraints an agent follows in conversation (what it asks, when it escalates, what it refuses) are authored in conversation topics. A backend process that moves data between services independently of the agent's reasoning is a Power Automate cloud flow. Agent flows run as part of the agent's actions, and Power Pages is a website product."},
"984461": {"exam": "AB-100", "n": 61, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Microsoft 365 Copilot for Sales summarizes email threads, suggests replies in Outlook and prepares meeting summaries enriched with CRM data from Dynamics 365, which is exactly the set of requirements."},
"984462": {"exam": "AB-100", "n": 62, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "A classic Dataverse workflow automates record updates and notifications; it cannot summarize email threads, draft replies in Outlook or produce meeting preparation summaries."},
"984463": {"exam": "AB-100", "n": 63, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "An agent template is a starting point for building a custom agent; it does not deliver Outlook email summaries, suggested replies and CRM-enriched meeting preparation, which Copilot for Sales provides out of the box."},
"994150": {"exam": "AB-100", "n": 64, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "A custom connector travels with the ALM process only when it is a component of Solution1, so it is exported and imported consistently; importing the solution as managed into other environments keeps the connector editable only in development. GitHub, sharing or the default solution do not give that lifecycle."},
"994151": {"exam": "AB-100", "n": 65, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "Computer use drives the web app from natural-language instructions and visual understanding of the screen, so it keeps working when the UI changes, with no change to the agent. Topics, agent flows or custom models would need rework for each UI change."},
"994152": {"exam": "AB-100", "n": 66, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Agent architecture & orchestration", "why": "AI Builder's invoice processing model extracts and validates data from invoices in any format, and a Copilot Studio agent with its flows routes approvals to Teams where users review and approve, all with minimal development. Logic Apps or Functions with Azure OpenAI require custom code, and a SharePoint agent only answers questions."},
"994153": {"exam": "AB-100", "n": 67, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "A custom connector wraps the warranty REST API with secure authentication and is called from the agent as a tool with no code. Screen scraping, managed-solution exports or the Fallback topic do not retrieve API data."},
"994154": {"exam": "AB-100", "n": 68, "boxes": ["The Fallback topic", "A tool (connector)"], "verdict": "confirmed", "confidence": "high", "kp": "Copilot Studio agent design", "why": "When input is unclear and no topic or tool matches, the Fallback system topic sends the default help message. Starting an external process such as retrieving order status is done by a tool, here a connector that generative orchestration invokes on request. Trigger phrases are not used with generative orchestration, and skills are retired."},
"994155": {"exam": "AB-100", "n": 69, "answer": "EF", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Copilot in Field Service helps dispatchers and service staff organize and resolve work orders, and the Field Service mobile app delivers Copilot assistance to technicians as they prepare for and complete appointments. Customer Service products and Copilot in Outlook do not cover field work orders."},
"994156": {"exam": "AB-100", "n": 70, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Agent architecture & orchestration", "why": "A Foundry agent connected to a Model Context Protocol server discovers and calls the tools the server publishes at runtime, so new tools become available without changing or redeploying the agent. A hub, Azure AI Search or Copilot Studio do not provide dynamic tool discovery."},
"994157": {"exam": "AB-100", "n": 71, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Dynamics 365 Copilot features", "why": "Opportunity summaries in Dynamics 365 Sales are customizable: an administrator configures which fields the summary includes, adding standard or custom fields and reordering them, which tailors how the summary is generated and presented."},
"994158": {"exam": "AB-100", "n": 72, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Power Automate flows automate actions around records; they cannot change how Copilot generates or presents opportunity summaries, which is configured in the Sales app's Copilot settings."},
"994159": {"exam": "AB-100", "n": 73, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "AI Builder lead scoring models score leads; they have no effect on the content or presentation of Copilot's opportunity summaries, which are configured through the summary field settings in Dynamics 365 Sales."},
"994160": {"exam": "AB-100", "n": 74, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Dynamics 365 Copilot features", "why": "Agent management in finance and operations apps is where users discover the available prebuilt agents, review what each does, and configure and activate them, which is what the CTO needs to compare agent templates. Immersive Home is the AI-first landing page for working with agents already in use, Copilot Studio builds custom agents, and Lifecycle Services manages environments."},
"994161": {"exam": "AB-100", "n": 75, "boxes": ["a custom connector", "the MCP server"], "verdict": "corrected", "confidence": "medium", "kp": "Agent architecture & orchestration", "why": "R&D already runs an MCP server with the product specifications and compliance data. In Copilot Studio an MCP server is exposed through a custom connector that describes the server, and the server is then added to the agent so its tools become callable. OData entities, Bot Service channels and Semantic Kernel do not surface that data to a Copilot Studio agent.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/agent-extend-action-mcp"},
"999653": {"exam": "AB-100", "n": 76, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Dynamics 365 Copilot features", "why": "Placing the opportunity summary widget on a form only decides where the existing Copilot summary is displayed; it does not change what the summary contains or how it is generated. Tailoring the summary is done by configuring its fields in the Sales app's Copilot settings."},
"1021236": {"exam": "AB-100", "n": 77, "boxes": ["No", "Yes", "No"], "verdict": "confirmed", "confidence": "medium", "kp": "Copilot Studio agent design", "why": "The specialists need the same agent in Teams and SharePoint; making it available in Microsoft 365 Copilot alone does not put it in a SharePoint site, which needs the separate SharePoint channel (and Teams is added through the Teams and Microsoft 365 Copilot channel). Managed solutions promoted through separate dev, test and production environments meet the ALM requirement, and sending only selected non-sensitive fields meets the data-minimization rule. Writing the recommendation straight into the approval fields when the response arrives skips the specialist's review and acceptance, so it fails the accountability requirement.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/publication-add-bot-to-sharepoint"},
"1021237": {"exam": "AB-100", "n": 78, "answer": "DE", "verdict": "confirmed", "confidence": "high", "kp": "Prompt engineering & evaluation", "why": "Microsoft's prompt quality metrics define Relevance as information focused on the intended task, which is what out-of-scope content violates, and Format Compliance as output that follows the required structure, which is the inconsistent bullet-and-heading layout. Accuracy is already met, Consistency is about stable quality across repeated runs, and Tone Alignment concerns organizational or audience standards.", "ref": "https://learn.microsoft.com/en-us/training/modules/manage-testing-ai-powered-business-solutions/4-validate-effective-copilot-prompt-best-practices"},
"1021238": {"exam": "AB-100", "n": 79, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Governance, security & compliance", "why": "The content filtering system on the Azure OpenAI deployment includes Prompt Shields for user prompt attacks and indirect attacks (hidden instructions embedded in grounding documents); you turn them on in the deployment's content filter configuration without writing code. Calling the standalone Azure AI Content Safety APIs means integrating them into the application, DLP policies prevent data leakage rather than prompt manipulation, and Content Understanding extracts content from documents.", "ref": "https://learn.microsoft.com/en-us/azure/ai-foundry/openai/concepts/content-filter"},
"1021239": {"exam": "AB-100", "n": 80, "answer": "AE", "verdict": "confirmed", "confidence": "medium", "kp": "Agent architecture & orchestration", "why": "A pro-code specialized agent that orchestrates calls to a third-party data source is built in Foundry Agent Service, and the Microsoft 365 Agents SDK (with the Agents Toolkit) surfaces it as a custom engine agent that users discover and use in Microsoft 365 Copilot and Teams. The Assistants API is the older Azure OpenAI API that Agent Service supersedes, the Foundry SDK is a client library rather than the channel layer, and Copilot Studio is the low-code alternative that would not be paired with these tools.", "ref": "https://learn.microsoft.com/en-us/microsoft-365/copilot/extensibility/overview-custom-engine-agent"},
"984464": {"exam": "AB-100", "n": 81, "answer": "C", "verdict": "confirmed", "confidence": "medium", "kp": "Monitoring & analytics", "why": "The case study's agent is built in Copilot Studio, which sends its conversation telemetry to Application Insights; that is where sensitive information such as user IDs and names shared with the agent can be captured and retained for later auditing. The Analytics tab aggregates metrics, Foundry tracing and monitoring apply to Foundry agents, and MCP is a tool protocol."},
"984465": {"exam": "AB-100", "n": 82, "boxes": ["Microsoft Copilot Studio", "the current time to complete the task today per instance"], "verdict": "corrected", "confidence": "high", "kp": "ROI & business value", "why": "Return on investment for a Copilot Studio agent comes from the Savings calculator on the agent's Monitor page, which asks for the estimated time (or cost) that another method takes to complete the task per run or per tool and reports the time and money the agent saved. The input it needs is therefore the current time to complete the task per instance; cumulative past time, per-instance cost or license cost are not what it uses.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-cost-savings"},
"984466": {"exam": "AB-100", "n": 83, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Future funding depends on showing month-over-month adoption, which the Analytics tab in Copilot Studio reports: sessions, engagement, usage trends and outcomes. Foundry evaluations measure answer quality, cost workbooks and Operator Insights are unrelated, and DPO is a fine-tuning technique."},
"984467": {"exam": "AB-100", "n": 84, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Agent architecture & orchestration", "why": "Bringing your own Foundry model into a Copilot Studio agent is done by creating a connection to Microsoft Foundry in the agent, after which the model can be selected in a prompt tool and invoked securely during conversations. Orchestration mode, skills and custom engine agents do not connect a model."},
"984468": {"exam": "AB-100", "n": 85, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Power Platform solutions package flows, agents, Dataverse tables and apps together with versioning and dependency tracking, and are the unit that is deployed between environments. GitHub Actions and Azure DevOps automate the pipeline but still move solutions."},
"984469": {"exam": "AB-100", "n": 86, "answer": "AD", "verdict": "confirmed", "confidence": "high", "kp": "Governance, security & compliance", "why": "Microsoft Purview governs AI use in Microsoft 365: DSPM for AI, DLP, audit logging of Copilot interactions, retention and policy-violation detection. Microsoft Defender identifies and mitigates AI-related security risks and protects the apps and data, with incidents investigated in Defender XDR. Content Safety filters harmful content in Azure AI apps, and Foundry RBAC controls access to Foundry resources."},
"984470": {"exam": "AB-100", "n": 87, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Prompt engineering & evaluation", "why": "Whether generated business reports are appropriate and meaningful is judged by how well the output aligns with the domain-specific task. User counts, resource usage and training time measure adoption and cost, not output quality."},
"984471": {"exam": "AB-100", "n": 88, "answer": "B", "verdict": "confirmed", "confidence": "low", "kp": "Governance, security & compliance", "why": "Data residency for agents and their grounding data is enforced by controlling where the Azure OpenAI and data resources may be deployed; Azure Policy's allowed-locations rules deny deployments outside the approved US and European regions and report non-compliant resources. Purview classifies and governs the data itself but does not enforce where resources run, which is why opinion is split."},
"984472": {"exam": "AB-100", "n": 89, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Custom connectors are solution components; managing them in a solution and deploying through Power Platform pipelines gives consistent dev-test-production promotion with the traceability and governance pipelines provide. Unmanaged imports, environment variables or re-hosting the APIs do not."},
"984473": {"exam": "AB-100", "n": 90, "boxes": ["Use a Microsoft Power Platform deployment pipeline.", "Use an Azure DevOps pipeline."], "verdict": "corrected", "confidence": "high", "kp": "ALM & deployment", "why": "A Copilot Studio agent is promoted through Power Platform deployment pipelines, which give dev-test-production stages, isolation and repeatable automated deployment. A Foundry agent is deployed as code and Azure resources from the repository, so an Azure DevOps pipeline automates it end to end; a Bicep file only declares infrastructure and still needs a pipeline to run it.", "ref": "https://learn.microsoft.com/en-us/power-platform/alm/pipelines"},
"984474": {"exam": "AB-100", "n": 91, "boxes": ["Generated answer rate and quality", "Topics by outcome"], "verdict": "corrected", "confidence": "high", "kp": "Monitoring & analytics", "why": "Effective, relevant responses are measured by the generated answer rate and quality insight; conversational outcomes (resolved, escalated, abandoned) are reported per topic in the Topics by outcome view. Satisfaction and reactions capture user sentiment, and tool use counts actions.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-improve-agent-effectiveness"},
"984475": {"exam": "AB-100", "n": 92, "answer": "CD", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Copilot extensions for Customer Service are packaged as solution components and promoted automatically through Power Platform pipelines. Unmanaged solutions in production, rebuilding agents per environment or storing transcripts in source control are not ALM practices."},
"984476": {"exam": "AB-100", "n": 93, "boxes": ["Run task-based scenarios that involve both apps.", "Track the successful completion of cross-app tasks."], "verdict": "confirmed", "confidence": "high", "kp": "Testing & quality", "why": "Coordinating tasks across Customer Service and Sales is validated with end-to-end task scenarios that span both apps, and success is measured by whether those cross-app tasks complete. Isolated per-app tests, visual checks, response time or click rates do not test coordination or relevance."},
"984477": {"exam": "AB-100", "n": 94, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "A central model registry with version history lets the security and compliance team review each release against earlier versions and roll back if needed, which protects business continuity. A quality gate alone keeps no history, generic version control does not manage model artifacts, and retirement schedules address a different risk."},
"984478": {"exam": "AB-100", "n": 95, "boxes": ["Application Insights", "Microsoft Power Apps", "Copilot Studio"], "verdict": "confirmed", "confidence": "medium", "kp": "Monitoring & analytics", "why": "Near-real-time telemetry comes from Application Insights connected to the agent, and usage and performance are monitored on the Copilot Studio Monitor page. Downloading sessions from Copilot Studio gives only a subset of the data (28 days, and each agent response is truncated to 512 characters); to see all activities of a full conversation Microsoft directs you to download transcripts through Power Apps from the Dataverse conversation transcript table, which is why Power Apps is the answer for full conversations.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-transcripts-studio"},
"984479": {"exam": "AB-100", "n": 96, "boxes": ["Run tests against the latest unpublished version of the agent.", "Add the flow to the agent as a tool."], "verdict": "corrected", "confidence": "high", "kp": "Testing & quality", "why": "Changes are validated before release by testing the latest unpublished version in the test pane, without touching production or live users. A desktop flow is only exercised as part of the agent's orchestration when it is added to the agent as a tool; the desktop console runs it outside the agent."},
"984480": {"exam": "AB-100", "n": 97, "answer": "BE", "verdict": "corrected", "confidence": "low", "kp": "Monitoring & analytics", "why": "To find why answers are inaccurate you need the Analytics views that explain individual failures: the quality of generated answers insight, which categorizes low-quality answers by reason such as knowledge source errors, and session information with outcomes, which lets you inspect the actual questions, sources and conversation flow. Topic resolution and overall engagement or survey rates show that something is wrong, not what caused it."},
"984481": {"exam": "AB-100", "n": 98, "answer": "AE", "verdict": "confirmed", "confidence": "medium", "kp": "ALM & deployment", "why": "Versioned, trackable training data is achieved by keeping it in Azure Blob Storage with blob versioning enabled, and consistent retraining by associating that storage location with the fine-tuning job so every run uses the approved dataset. Azure Files has no versioning, ad-hoc file uploads lose traceability, and content filters are a safety setting."},
"984482": {"exam": "AB-100", "n": 99, "boxes": ["Azure Policy", "Microsoft Defender for Cloud"], "verdict": "corrected", "confidence": "high", "kp": "Governance, security & compliance", "why": "Azure Policy's allowed-locations rules deny resource deployments outside the approved regions. Continuous compliance verification of the deployed resources is Microsoft Defender for Cloud's regulatory compliance dashboard, which keeps assessing them against standards. Purview governs data rather than resource compliance, and Monitor and Sentinel are telemetry and SIEM."},
"984483": {"exam": "AB-100", "n": 100, "answer": "E", "verdict": "confirmed", "confidence": "medium", "kp": "Governance, security & compliance", "why": "Microsoft Purview provides ready-made auditing and data governance across Azure AI services: it records who changed what in the AI assets and how data is used, with little setup. Azure Monitor and Policy need custom alerting and policies, and Stream Analytics and API Management are not governance tools."},
"984484": {"exam": "AB-100", "n": 101, "boxes": ["Microsoft Purview access policies", "Role-based access control (RBAC) in Microsoft Foundry"], "verdict": "confirmed", "confidence": "high", "kp": "Governance, security & compliance", "why": "Access to grounding data in Microsoft Fabric is governed centrally with Microsoft Purview access policies that grant it only to assigned roles, and fine-tuning in Foundry is restricted to the AI engineering team through Foundry's role-based access control. Content Safety, Monitor alerts, resource locks and Conditional Access do not scope those permissions."},
"984485": {"exam": "AB-100", "n": 102, "boxes": ["Generated answer rate and quality", "Conversation outcomes"], "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "The generated answer rate and quality insight reports how many questions got no answer, and conversation outcomes break sessions into resolved, escalated and abandoned. Reactions and survey results measure sentiment, not these counts."},
"984486": {"exam": "AB-100", "n": 103, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Testing & quality", "why": "Dashboards for resolution, deflection and accuracy measure effectiveness during active sessions and give actionable numbers, and scripted interactions check that responses stay accurate and consistent. Load tests, uptime and ticket history do not evaluate response quality."},
"984487": {"exam": "AB-100", "n": 104, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Application Insights collects comprehensive telemetry and performance data from Copilot Studio agents across every channel. Azure Advisor recommends resource optimizations, Azure DevOps runs pipelines, and Customer Voice collects surveys."},
"984488": {"exam": "AB-100", "n": 105, "answer": "AD", "verdict": "confirmed", "confidence": "high", "kp": "ROI & business value", "why": "Reduced average case resolution time and increased employee productivity are measurable drivers that the Copilot Studio solution directly changes. Market capitalization, market predictability and brand awareness are not measurable effects of the solution."},
"994162": {"exam": "AB-100", "n": 106, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Data preparation & grounding", "why": "Chunking documents at indexing time makes retrieval return small, relevant passages instead of large blocks, so fewer tokens reach the model while the answer still has the facts it needs. Dropping knowledge sources, capping retrieved content by prompt or lowering the response limit all reduce tokens by removing information and risk degrading quality."},
"994163": {"exam": "AB-100", "n": 107, "boxes": ["Agent1 and references to the data sources", "The Dataverse and Azure AI Search connections"], "verdict": "corrected", "confidence": "medium", "kp": "ALM & deployment", "why": "The deployment package holds the agent and connection references to its data sources, never the environment-specific tables, index or credentials. After importing into production, the connections behind those references are set to the production Dataverse and Azure AI Search endpoints, so the agent uses production grounding data with credentials kept out of the package."},
"994164": {"exam": "AB-100", "n": 108, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Resolution and escalation rates, abandoned sessions and topic outcomes for a Copilot Studio agent are analysed in its Analytics tab, which is where the cause of a low resolution rate is found. Customer Service dashboards cover human agents, and the Microsoft 365 and Power Platform admin centers report usage, not conversation outcomes."},
"994165": {"exam": "AB-100", "n": 109, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Prompt engineering & evaluation", "why": "AI-assisted quality metrics use a model such as GPT-4o as a judge to score coherence, fluency and relevance numerically. NLP metrics are formula-based (BLEU, ROUGE), risk and safety metrics measure harm, and groundedness is one specific metric rather than overall quality."},
"994166": {"exam": "AB-100", "n": 110, "boxes": ["Escalation rate", "Answer quality"], "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "The escalation rate is the share of engaged sessions handed to a representative. Queries that fail because of a knowledge source error are counted in the answer quality insight, which categorizes why generated answers were poor or missing."},
"994167": {"exam": "AB-100", "n": 111, "answer": "C", "verdict": "confirmed", "confidence": "medium", "kp": "Prompt engineering & evaluation", "why": "Evaluating an agent against baseline accuracy metrics before deployment, and watching for drift afterwards, is what Foundry's observability capabilities provide: evaluation runs, quality thresholds and drift monitoring. GitHub Actions can orchestrate the pipeline but does not itself evaluate, and Application Insights reports runtime telemetry."},
"994168": {"exam": "AB-100", "n": 112, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Governance, security & compliance", "why": "Power Platform data loss prevention policies classify connectors as business, non-business or blocked, so agents can only use approved connectors and cannot reach sensitive data through others. Auditing, monitoring and customer-managed keys record or encrypt access rather than restrict it."},
"994169": {"exam": "AB-100", "n": 113, "answer": "CD", "verdict": "confirmed", "confidence": "high", "kp": "Prompt engineering & evaluation", "why": "Effective prompts give clear, specific instructions and are tested and refined continuously against real user input. Session duration, prompt length statistics and resource usage do not improve prompt quality."},
"994170": {"exam": "AB-100", "n": 114, "boxes": ["Microsoft Purview", "Azure Monitor"], "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Compliance monitoring of AI apps and agents, including sensitive data use and policy violations, is Microsoft Purview; performance metrics and operational health of Azure OpenAI models are Azure Monitor. Both are Azure-native and need no custom development."},
"994171": {"exam": "AB-100", "n": 115, "answer": "AE", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "Agents and custom connectors are placed in a solution so they move consistently between environments, and production receives the managed version of that solution, which prevents direct editing there. Unmanaged solutions, rebuilding or data export do not give that control."},
"994172": {"exam": "AB-100", "n": 116, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Application Insights is the telemetry service Copilot Studio integrates with for comprehensive, cross-channel performance insight; Log Analytics is only the workspace that stores it, Purview governs compliance, and Customer Voice collects surveys."},
"994173": {"exam": "AB-100", "n": 117, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Responsible AI", "why": "The solution uses an Azure OpenAI foundation model whose training data cannot be edited, so the fairness fix for a production system is to change the system instructions to require consistent, trait-neutral marketing content. Random output does not remove bias, and retraining or editing the training set is not possible for the hosted model."},
"994174": {"exam": "AB-100", "n": 118, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Governance, security & compliance", "why": "Copilot features in Power Apps are not available in environments that use a customer-managed key, and the current encryption configuration must stay as it is, so the only way to add Copilot components to App1 is to move the app to an environment with Microsoft-managed keys.", "ref": "https://learn.microsoft.com/en-us/power-apps/maker/canvas-apps/add-ai-copilot"},
"994175": {"exam": "AB-100", "n": 119, "answer": "CE", "verdict": "confirmed", "confidence": "high", "kp": "ALM & deployment", "why": "The custom Copilot Studio agent travels in a Power Platform solution, and the Supply Chain Management business logic it uses lives outside the app as X++ customizations packaged as an X++ model. Cloud Scale Unit packages are for Commerce, and ZIP or Azure packages are transport formats, not ALM components."},
"994176": {"exam": "AB-100", "n": 120, "boxes": ["Azure Resource Graph Explorer", "Microsoft Purview"], "verdict": "corrected", "confidence": "high", "kp": "Governance, security & compliance", "why": "The CISO must discover and inventory AI resources across Contoso's multiple Azure subscriptions, which is what Azure Resource Graph Explorer queries do at scale. The CIO must make sure the data used by the agents carries the right security labels, which is Microsoft Purview's sensitivity labelling and data governance."},
"994177": {"exam": "AB-100", "n": 121, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Responsible AI", "why": "The CEO needs quarterly, Microsoft-recommended assessments of reliability, interpretability, fairness and compliance, which the Responsible AI dashboard delivers: model performance, error analysis, fairness and interpretability views. Purview governs data, the Service Trust Portal and Compliance Center document Microsoft's own compliance, and Foundry Tools are the AI services."},
"994178": {"exam": "AB-100", "n": 122, "boxes": ["Effectiveness", "Satisfaction"], "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "The CFO wants to compare abandoned sessions with resolved ones to spot inefficient credit use; those conversation outcomes (Resolved, Escalated, Abandoned, Unengaged) are reported in the Effectiveness section of the Monitor page. The CTO's concern about poor feedback on responses is the Satisfaction analytics (reactions, CSAT survey scores). Use covers answer rate, tool use and knowledge source use, and Tool use counts actions.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-improve-agent-effectiveness"},
"999654": {"exam": "AB-100", "n": 123, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Agent types & use cases", "why": "GitHub Copilot assists developers writing code; it does not build a customer-facing generative agent, report agent analytics or analyse customer demographics."},
"999655": {"exam": "AB-100", "n": 124, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Agent types & use cases", "why": "Security Copilot supports security operations (incidents, threats, alerts); it is not a platform for building a customer-analysis agent with its own analytics."},
"999656": {"exam": "AB-100", "n": 125, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Agent types & use cases", "why": "Copilot Studio builds generative agents with little custom development, ships analytics to review agent performance, and connects to customer data sources to surface demographics, so it meets all four requirements."},
"999657": {"exam": "AB-100", "n": 126, "answer": "C", "verdict": "confirmed", "confidence": "low", "kp": "Monitoring & analytics", "why": "Copilot Studio agents send their telemetry to Application Insights, whose data lives in a Log Analytics workspace where it can be queried and monitored across all agents and channels; of these options that is the comprehensive telemetry store. The Analytics area in Copilot Studio gives built-in performance insights but not raw telemetry, Power BI only visualizes, and Azure Advisor recommends resource changes."},
"1021240": {"exam": "AB-100", "n": 127, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "ALM & deployment", "why": "Lifecycle Services is the collaboration portal for managing the application lifecycle of finance and operations implementations; it links to the Azure DevOps project for source control, builds and deployable packages, and manages environments and deployments. Power Platform pipelines are an alternative deployment tool to Azure DevOps, solutions are a packaging container rather than a management solution, and Azure DevOps test plans cover only testing.", "ref": "https://learn.microsoft.com/en-us/dynamics365/fin-ops-core/dev-itpro/lifecycle-services/lcs"},
"1021241": {"exam": "AB-100", "n": 128, "boxes": ["Yes", "No", "Yes"], "verdict": "confirmed", "confidence": "medium", "kp": "Governance, security & compliance", "why": "A Data Zone deployment in a US Foundry resource processes prompts and responses only within the US data zone, which satisfies the US-only processing requirement. Copying full grounding documents into the audit log breaks the rule that audit records capture only metadata and would spread sensitive data. Microsoft Entra pass-through authentication makes each data call run as the signed-in user, so the data source returns only what that user's identity is permitted to see.", "ref": "https://learn.microsoft.com/en-us/azure/foundry/foundry-models/concepts/deployment-types"},
"1021242": {"exam": "AB-100", "n": 129, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Monitoring & analytics", "why": "Reactions are the thumbs up and thumbs down (with optional comments) that users give on specific agent responses, shown in the Effectiveness section of the Monitor page. Survey results produce a session-level CSAT score, conversation outcomes classify sessions as resolved, escalated or abandoned, and tool use counts tool calls.", "ref": "https://learn.microsoft.com/en-us/microsoft-copilot-studio/analytics-improve-agent-effectiveness"},
"1000629": {"exam": "AI-103", "n": 1, "boxes": ["Standard", "Opt out of automatic model version upgrades"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Pay-as-you-go deployments scale with traffic without reserved capacity, so the choice is between Standard and Global Standard; because the data processed by the model must stay in the EU, the regional Standard deployment (in the EU project region) is required, since Global Standard may route requests to any geography. Keeping the model version consistent means opting out of automatic version upgrades.", "ref": "https://learn.microsoft.com/en-us/azure/foundry/foundry-models/concepts/deployment-types"},
"1000630": {"exam": "AI-103", "n": 2, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Planning & managing Azure AI solutions", "why": "The security requirement that names a specific threat is protection from malicious instructions hidden in the text of product-sheet images, an indirect prompt-injection attack that Prompt Shields are built to detect and block. Self-harm and violence filters target harmful content, and PII detection would address customer data but is a Language feature rather than an agent guardrail against hidden instructions.", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/content-safety/concepts/jailbreak-detection"},
"1000631": {"exam": "AI-103", "n": 3, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "A project connection stores the Azure AI Search endpoint and credential once, and every agent in Project1 references it, which is central credential management. RBAC and disabling keys are security hardening, and a private endpoint is network isolation; neither centralizes credentials."},
"1000632": {"exam": "AI-103", "n": 4, "boxes": ["No", "Yes", "No"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Configuring Azure Monitor for the Foundry project does not instrument a separate LangChain service; it needs its own tracer to appear in Traces. Each service's OTEL_SERVICE_NAME becomes the cloud role name in Application Insights, which keeps the two distinguishable. With enable_content_recording=False, prompts, completions and tool arguments are not recorded in the spans, which is how secrets stay out of the telemetry."},
"1000633": {"exam": "AI-103", "n": 5, "boxes": ["Single-file task in standard mode", "Multi-file task in pro mode"], "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Standard mode extracts fields from individual documents cheaply at volume, which fits standalone PDF invoices. Pro mode handles multi-step reasoning across several input files plus reference data, which is what cross-document validation needs, so Pipeline2 is a multi-file task in pro mode."},
"1000634": {"exam": "AI-103", "n": 6, "boxes": ["DefaultAzureCredential", "create"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "DefaultAzureCredential picks up the app's managed identity (and a developer's az login locally), whereas AzureKeyCredential needs a key and ClientSecretCredential a service principal secret. Sending a prompt through the Responses API is responses.create(); retrieve fetches an existing response."},
"1000635": {"exam": "AI-103", "n": 7, "boxes": ["Not(IsBlank(Local.Var01))", "{Upper(Local.Var01)}"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "IsBlank tests a variable for a blank value, so the condition that the variable contains a value is Not(IsBlank(Local.Var01)); IsEmpty is for tables. The message returns the value in uppercase with Upper(), and the variable is addressed through the Local scope: {Upper(Local.Var01)}."},
"1000636": {"exam": "AI-103", "n": 8, "boxes": ["Select User input, Output, Tool response, and Tool call and set Action to Block.", "A system-assigned managed identity that is assigned the Storage Blob Data Contributor role"], "verdict": "corrected", "confidence": "high", "kp": "Computer vision solutions", "why": "To prevent harmful content, not just label it, the guardrail must block at every point where images and text enter or leave the run: user input, tool call, tool response and output. For Content Safety to read screenshots through their blob URL it uses the resource's system-assigned managed identity, and the documented requirement for blob URL access is the Storage Blob Data Contributor (or Owner) role; access keys are the least secure option and the Reader role is not accepted for this scenario.", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/content-safety/quickstart-image"},
"1000637": {"exam": "AI-103", "n": 9, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A Foundry workflow is a deterministic, step-based orchestration with conditional branching and shared state between agents, and an optional ticket step is just a conditional branch, with no custom code. Group chats are non-deterministic, and threads or app-code coordination means writing the orchestration yourself."},
"1000638": {"exam": "AI-103", "n": 10, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "A fine-tuned (custom) speech model belongs to a custom speech project, and the Speech to text REST API's project parameter expects that custom speech project's ID, not the Foundry project ID and not a URL."},
"1000639": {"exam": "AI-103", "n": 11, "boxes": ["ask_question", "approval == \"approved\""], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "An ask_question step pauses the workflow and waits for a human answer, storing it for later steps. The refund step then runs only when the approval step's answer equals \"approved\"; a condition of true would always run it, and checking that the proposal produced output does not require approval."},
"1000640": {"exam": "AI-103", "n": 12, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "When a custom speech model on a custom endpoint expires, real-time recognition requests automatically fall back to the most recent base model for that locale, so the service keeps working with possibly lower accuracy. The model is not deleted, not kept in use, and requests do not fail (batch transcription with an expired model is the case that errors)."},
"1000641": {"exam": "AI-103", "n": 13, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "A 403 after a successful sign-in means the identity lacks the data-plane permission to call the model. Cognitive Services OpenAI User grants exactly inference on Azure OpenAI deployments and nothing more. Contributor is control-plane and over-privileged, Cognitive Services User targets other services, and Data Reader does not allow inference."},
"1000642": {"exam": "AI-103", "n": 14, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Generative AI & agentic solutions", "why": "Setting tool_choice to required forces the model to call a tool on every run instead of answering from its own knowledge, which is what guarantees the knowledge base is consulted. auto leaves the decision to the model, and the other two forms are not valid tool_choice values."},
"1000643": {"exam": "AI-103", "n": 15, "boxes": ["Groundedness evaluation metrics", "Risk and safety metrics"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Answers not supported by the retrieved documents are a groundedness failure, measured by the groundedness evaluator. Responses flagged for policy violations are measured by the risk and safety evaluators. Latency traces and token analytics describe performance and cost."},
"1000644": {"exam": "AI-103", "n": 16, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Declaring an apiKey security scheme (in: header) in the OpenAPI specification lets the OpenAPI tool inject the key stored in the project connection into that header on every call. A per-operation header parameter would need the value supplied manually, a bearer scheme is for OAuth tokens, and Key Vault is not an OpenAPI construct."},
"1000645": {"exam": "AI-103", "n": 17, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A model cascade (router) sends simple FAQ requests to a small, cheap, fast model and escalates complex questions to a more capable model, cutting cost and latency for the common case without degrading hard answers. Routing everything to one model sacrifices either quality or cost, and max_tokens changes neither."},
"1000646": {"exam": "AI-103", "n": 18, "boxes": ["Model Availability Rate and Provisioned Utilization", "RequestResponse"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Model Availability Rate shows whether the deployment was unavailable, and Provisioned Utilization shows whether capacity limits are being hit, which explains 429 errors at peak. The RequestResponse diagnostic log records each request and its outcome, which is needed to see why queries end in \"no relevant information found\" rather than inference errors."},
"1000647": {"exam": "AI-103", "n": 19, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Cost is billed per token, and token usage observability breaks consumption down into prompt (input) tokens, completion (output) tokens and tool-related tokens, so it shows which of the three grew. Latency, evaluation metrics and run success rate do not attribute cost."},
"1000648": {"exam": "AI-103", "n": 20, "boxes": ["required", "Using a distinct agent identity bound to the client application"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "tool_choice required makes every run call a tool, so the retrieval step always happens before the response; auto lets the model skip it and none disables tools. A distinct agent identity bound to the client application gives the published agent its own isolated, auditable identity for tool calls, unlike a shared project identity or keys in prompts."},
"1000649": {"exam": "AI-103", "n": 21, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "The key header is missing because the tool is not bound to the connection that holds the key; connecting the OpenAPI tool to Connection1 makes Foundry add the key automatically. Identity passthrough sends an Entra token instead, hard-coding the header puts a secret in the spec, and the project's default connection is not Connection1."},
"1000650": {"exam": "AI-103", "n": 22, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Tracing records each run as an ordered set of spans: every model call, tool invocation and their timings, which is what diagnosing slow runs and wrong answers despite correct tool data requires. Token usage, monitoring and safety metrics are aggregates."},
"1000651": {"exam": "AI-103", "n": 23, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Computer vision solutions", "why": "A prompt shield for user prompts detects jailbreak attempts typed by the user; instructions hidden inside uploaded images arrive as extracted document content, which the user-prompt shield does not inspect, and it does nothing about unsafe image content."},
"1000652": {"exam": "AI-103", "n": 24, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Computer vision solutions", "why": "Image moderation blocks unsafe visual content, but it cannot recognise hidden instructions in the text extracted from an image, so the manipulation risk the question is about remains."},
"1000653": {"exam": "AI-103", "n": 25, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Computer vision solutions", "why": "The risk has two parts: unsafe images, and hidden instructions carried in the text extracted from images. Prompt Shields for documents detects indirect attacks embedded in third-party content such as documents, emails and web pages, so it can catch injected instructions once they are extracted as text, but it does nothing about unsafe image content, so on its own it does not mitigate the stated risk. Each proposed solution in this series addresses only one half of the problem, which is why none of them meets the goal; image moderation plus Prompt Shields together would.", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/content-safety/concepts/jailbreak-detection"},
"1000654": {"exam": "AI-103", "n": 26, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Protected material detection flags copyrighted text or code in model output; it has nothing to do with unsafe images or instructions hidden in them."},
"1000655": {"exam": "AI-103", "n": 27, "answer": "D", "verdict": "confirmed", "confidence": "medium", "kp": "Generative AI & agentic solutions", "why": "Assessing whether Agent1's answers are accurate and complete with respect to the product sheets is a groundedness check: the evaluator scores how well each response is supported by the retrieved context. Guardrails and fine-tuning do not assess responses, and the broader RAG evaluator set includes retrieval metrics that are not what is asked."},
"1000656": {"exam": "AI-103", "n": 28, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Restricting the agent to Contoso products is a scope rule, which belongs in the system message instructions (answer only about Contoso products, decline anything else). Few-shot examples shape style, and temperature or top-p only change randomness."},
"1000657": {"exam": "AI-103", "n": 29, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Deep multi-step reasoning over long retrieved contexts and detailed natural-language answers are the strengths of a large language model. A small model trades reasoning depth for cost, a multimodal model adds image or audio input that is not needed, and key phrase extraction is a narrow NLP task."},
"1000658": {"exam": "AI-103", "n": 30, "boxes": ["\"tool_choice\"", "\"required\""], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "The run payload's tool_choice key set to \"required\" forces the agent to call a tool during the run; \"auto\" leaves it optional, and the other keys configure tools or output format rather than forcing a call."},
"1000659": {"exam": "AI-103", "n": 31, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "One Azure AI Search connection in Project1, authenticated with Microsoft Entra ID instead of a key, gives every client app the same search configuration with the least administrative effort. Per-app endpoints, direct calls or per-app managed identities duplicate configuration."},
"1000660": {"exam": "AI-103", "n": 32, "boxes": ["Grounding with Bing Search", "Code interpreter", "File search"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Grounding with Bing Search brings in current public-web information, the code interpreter runs code to perform calculations during the conversation, and file search retrieves content from documents uploaded directly to the agent."},
"1000661": {"exam": "AI-103", "n": 33, "answer": "BC", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A Python service outside the portal is instrumented with OpenTelemetry, and the traces (latency breakdown, exceptions) are collected and viewed in the project's Application Insights resource; either, as described, completes the tracing solution. A Log Analytics workspace only stores data, and the Azure Monitor Agent and Sentinel do not trace agent runs."},
"1000662": {"exam": "AI-103", "n": 34, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A conversation (thread) in the Foundry Agent Service is server-side state that keeps every user message, agent message, tool call and tool output; storing its ID and supplying it on later requests, even days later, reloads the full history on each turn. Keeping only the last response loses the history, and memory summarization condenses it instead of reloading it."},
"1000663": {"exam": "AI-103", "n": 35, "boxes": ["0", "\"high\""], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Temperature 0 makes the output as deterministic as possible, which removes the small wording differences that break validation. Setting the reasoning effort to high keeps reasoning quality at its maximum."},
"1000664": {"exam": "AI-103", "n": 36, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Agentic retrieval in Azure AI Search plans the query from the whole conversation, breaks a complex question into subqueries that fetch several chunks, and runs those subqueries in parallel. Classic RAG is a single query, iterative retrieval runs sequentially, and chain of thought is a prompting technique."},
"1000665": {"exam": "AI-103", "n": 37, "boxes": ["Agent memory that uses persistent storage", "File search tool"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Preferences that must survive across conversations need agent memory backed by persistent storage; conversation history and session context end with the conversation. Documents a user uploads during a chat are made searchable to the agent by the file search tool, whereas the Azure AI Search tool queries a prebuilt index."},
"1000666": {"exam": "AI-103", "n": 38, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A completeness fix in application code before the response is returned is an evaluate-and-retry step: check the draft against the retrieved documents and regenerate when something is missing. Fewer tokens or a smaller model make summaries less complete, and the agent already uses retrieval."},
"1000667": {"exam": "AI-103", "n": 39, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "HTTP 429 means the deployment's rate limit was hit; retrying with exponential backoff and jitter spreads the retries so calls succeed within the existing limits. Immediate retries make throttling worse, and tools or file sizes do not affect rate limits."},
"1000668": {"exam": "AI-103", "n": 40, "boxes": ["An Azure Login action that uses OpenID Connect (OIDC)", "Fail"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "GitHub Actions authenticates to Azure with the Azure Login action using OIDC federated credentials, so no secret or PAT is stored and a managed identity is not available to GitHub-hosted runners. To block the merge when evaluation thresholds are not met, the workflow step must fail, which fails the required check; alerts or branch locks do not gate the pull request."},
"1000669": {"exam": "AI-103", "n": 41, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "The clauses are present in the retrieved content but left out of the summary, so the problem is what the model chooses to include, not output truncation; allowing a longer response does not make it include them."},
"1000670": {"exam": "AI-103", "n": 42, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A reflection pass checks the draft against the required clauses and regenerates the response when any is missing, which directly enforces completeness."},
"1000671": {"exam": "AI-103", "n": 43, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Raising the temperature only adds randomness; it does not make the model include required clauses and can make omissions more frequent."},
"1000672": {"exam": "AI-103", "n": 44, "answer": "B", "verdict": "confirmed", "confidence": "medium", "kp": "Generative AI & agentic solutions", "why": "Scoring completeness and blocking responses below a threshold stops incomplete summaries from reaching users, but it does not improve them: the user gets no answer instead of a complete one. Completeness improves only when the response is regenerated or the instructions are changed."},
"1000673": {"exam": "AI-103", "n": 45, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Mask-based inpainting edits only the masked region of the supplied image and leaves the rest, including lighting and style, untouched; it needs the input image and a mask. Variation, text-to-image and high-strength image-to-image regenerate the whole image."},
"1000674": {"exam": "AI-103", "n": 46, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Removing a single element while preserving everything else is mask-based inpainting over the logo region. Changing the prompt, guidance or seed regenerates the whole image."},
"1000675": {"exam": "AI-103", "n": 47, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "The prebuilt-layout analyzer extracts content with its layout elements (sections, tables, reading order) and detects barcodes and QR codes, and it needs no language model deployment. prebuilt-read is plain OCR, documentSearch targets RAG chunking, and documentFieldSchema proposes field schemas."},
"1000676": {"exam": "AI-103", "n": 48, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Computer vision solutions", "why": "When generating from a supplied product photo, the input_fidelity parameter set to high tells the image model to preserve the identity and visual details of the input image. Temperature does not apply to image generation, groundedness is a text evaluator, and supplying the image alone does not guarantee fidelity."},
"1000677": {"exam": "AI-103", "n": 49, "boxes": ["Set action to block.", "Enable Spotlighting."], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "To prevent injection from text embedded in screenshots, the document-attack prompt shield is set to block. Spotlighting marks third-party content so the model treats it as lower-trust data rather than instructions, which is the additional mitigation asked for; blocklists match terms and OCR alone adds no trust separation."},
"1000678": {"exam": "AI-103", "n": 50, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Image moderation in Azure AI Content Safety classifies images into harm categories with severity levels, so content can be blocked above a chosen severity. OCR keyword scans only see text, prompt shields target injection, and blocklists match terms."},
"1000679": {"exam": "AI-103", "n": 51, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "OCR text appended to the prompt is third-party document content, so Prompt Shields for documents is what detects malicious instructions hidden in it. The user-prompt shield covers what the user types, image moderation covers harmful visuals, and protected material covers copyright."},
"1000680": {"exam": "AI-103", "n": 52, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "A Content Understanding analyzer turns mixed-format documents with scanned text, tables and multi-column layouts into structure-preserving Markdown, which is the first step before any reasoning. Language models and chat requests consume that Markdown; they do not extract it."},
"1000681": {"exam": "AI-103", "n": 53, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Content Understanding provides OCR, layout analysis and field extraction that generalizes across invoice templates without training a custom model. The Language service is text analytics, and an Azure Machine Learning model would have to be built and trained."},
"1000682": {"exam": "AI-103", "n": 54, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Advanced data parsing uses the Document Intelligence layout model during ingestion: it runs OCR on scanned pages, keeps tables and headings as structure-aware chunks, and stores page-number metadata with each chunk. Page-level OCR chunks and basic fixed-size chunking split tables and lose structure."},
"1000683": {"exam": "AI-103", "n": 55, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "The built-in OCR skill reads images from the indexer's normalized_images collection, which is produced when the indexer is configured to extract image data (imageAction). A Shaper skill reshapes data, OCR cannot run on the text content field, and output field mappings write results rather than extract images."},
"1000684": {"exam": "AI-103", "n": 56, "answer": "C", "verdict": "confirmed", "confidence": "medium", "kp": "Information extraction solutions", "why": "The finance department needs invoices with varied layouts, tables and logos analysed for both visual layout and textual content and then verified against contract terms. Azure Content Understanding does multimodal document analysis with reasoning across documents (pro mode), which covers that end to end; Document Intelligence extracts invoice fields but does not reason against contracts, and image analysis or chat completions do not extract document structure."},
"1000685": {"exam": "AI-103", "n": 57, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Enabling estimateFieldSourceAndConfidence makes the Content Understanding document analyzer return a confidence score and a source location (page and bounding region) for each extracted field, which is what verification and routing of low-confidence values require."},
"1000686": {"exam": "AI-103", "n": 58, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "Transcripts that appear within seconds of a continuous audio stream require real-time speech to text. Batch transcription processes recorded files later, and text to speech or translation do not transcribe live calls."},
"1000687": {"exam": "AI-103", "n": 59, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "A low-latency voice agent with natural turn-taking uses real-time speech to text on the incoming audio and text to speech for the spoken replies. Batch transcription is too slow, embeddings do not transcribe, and translation changes language rather than enabling speech."},
"1000688": {"exam": "AI-103", "n": 60, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "Translator handles one source language per segment, so splitting mixed English and Spanish segments into single-language pieces and translating each gives complete, correct output. Auto-detection picks one language per segment, forcing English mistranslates the Spanish, and document translation has the same mixed-language problem."},
"1000689": {"exam": "AI-103", "n": 61, "answer": "AC", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "An indexing pipeline that enables semantic and vector search over the product sheets needs the Text Split skill to chunk the PDFs and the Azure OpenAI Embedding skill to vectorize each chunk. Entity recognition, merge, language detection and key phrases do not produce vectors."},
"1000690": {"exam": "AI-103", "n": 62, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "The planned change is an indexing pipeline with semantic and vector search so Agent1 can retrieve product information from storage1, which is Azure AI Search. Translator and Bing grounding do not index private PDFs, and Document Intelligence extracts content but is not the retrieval layer."},
"1000691": {"exam": "AI-103", "n": 63, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "The Document Intelligence layout model returns Markdown that keeps sections and tables when the request sets the output content format to Markdown, in the SDK output_content_format=ContentFormat.MARKDOWN. Figures output, confidence thresholds and a content=markdown parameter do not do this."},
"1000692": {"exam": "AI-103", "n": 64, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Extracting a defined set of invoice fields across varying templates and returning per-field confidence scores for routing is a custom Content Understanding analyzer with those fields in its schema and confidence estimation enabled. prebuilt-layout has no custom fields, search.score is retrieval relevance, and guardrails do not extract fields."},
"1000693": {"exam": "AI-103", "n": 65, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Groundedness evaluation scores how well each response is supported by the retrieved context, so a drop after a content update shows whether the retrieved content is misleading the model. Indexer status, latency traces and drift metrics do not measure that relationship."},
"1009423": {"exam": "AI-103", "n": 66, "boxes": ["create", "retrieve"], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Video generation is asynchronous: client.videos.create starts the job and returns its ID and status, and the loop polls client.videos.retrieve(video.id) until the status is completed, failed or cancelled. list returns all jobs and download_content fetches the finished file."},
"1009424": {"exam": "AI-103", "n": 67, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Personalized interactions that retain conversation context and recall information from previous interactions are provided by agent memory. Knowledge supplies product facts, tools perform actions, and guardrails restrict behaviour."},
"1009425": {"exam": "AI-103", "n": 68, "boxes": ["DefaultAzureCredential()", "get"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Developers must use Microsoft Entra authentication and no API keys, so the project client is created with DefaultAzureCredential, which honours the SC_Agent1_Dev group's role assignments. Retrieving an existing agent by name is agents.get; create_version would make a new version and get_version needs a specific version."},
"1009426": {"exam": "AI-103", "n": 69, "answer": "AD", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Claims not supported by the retrieved content are measured by the groundedness evaluator, and retrieved content that does not match the labelled expected context is measured by the retrieval evaluator. Fluency, coherence and response completeness assess other qualities."},
"1009427": {"exam": "AI-103", "n": 70, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A conversation is the durable, server-side state in the Foundry Agent Service: its ID is reused across turns and sessions and it preserves user messages, agent messages, tool calls and tool outputs. A response or output item is a single result, and the agent is the definition."},
"1009428": {"exam": "AI-103", "n": 71, "boxes": ["Groundedness and Relevance", "Protected material"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Whether a response is supported by the context is groundedness and whether it addresses the query is relevance; both are AI-assisted quality metrics. Sensitive or proprietary content in responses is flagged by the protected material evaluation. Similarity, ROUGE and F1 compare with ground truth, and the harm categories measure other risks."},
"1009429": {"exam": "AI-103", "n": 72, "answer": "AE", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Groundedness and relevance are AI-assisted quality metrics, scored by a judge model, and harmful content categories are risk and safety metrics. NLP metrics such as BLEU or ROUGE compare text overlap and cannot judge groundedness; fluency and similarity evaluators measure other things."},
"1009430": {"exam": "AI-103", "n": 73, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "To force one specific tool on a run, tool_choice names that tool by type; the Bing grounding tool is the one that searches the internet. required would force some tool without choosing which, auto lets the model decide, and the Azure AI Search tool reads the private index."},
"1009431": {"exam": "AI-103", "n": 74, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Temperature controls randomness, so lowering it makes identical prompts produce consistent responses without touching the prompt or accuracy. Raising it increases variation, and max_tokens or stop sequences affect length, not variability."},
"1009432": {"exam": "AI-103", "n": 75, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Showing the model examples of correct classifications inside the prompt is few-shot learning: in-context examples that improve accuracy without retraining or storing anything. Zero-shot gives no examples, chain of thought asks for reasoning steps, and RAG retrieves knowledge."},
"1009433": {"exam": "AI-103", "n": 76, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Generative AI & agentic solutions", "why": "The memory search tool's scope partitions the memory store; the docs describe {{$userId}} for per-user memory that follows the user across sessions, or a static value shared by everyone. Memory that must not persist across separate sessions needs a scope bound to the session rather than the user or a global value, which is the session option. (Microsoft Learn currently documents only the user and static scopes, so this answer follows the question's own option set.)", "ref": "https://learn.microsoft.com/en-us/azure/foundry/agents/how-to/memory-usage"},
"1009434": {"exam": "AI-103", "n": 77, "boxes": ["\"{{$userId}}\"", "[memory_tool]"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Scoping the memory search tool to {{$userId}} isolates stored memories per authenticated user and lets preferences carry across conversations, with the user ID resolved by the service rather than generated by the client. The agent definition receives the tool in its tools list, so tools=[memory_tool]."},
"1009435": {"exam": "AI-103", "n": 78, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Application tracing in the project records every step of a request as spans: the Responses API call, the Content Safety tool call through the connection, and their timings, which is end-to-end visibility. Content Safety's own logging covers only its call, Foundry Local is for on-device models, and routing changes nothing about visibility."},
"1009436": {"exam": "AI-103", "n": 79, "boxes": ["The sequential template that passes outputs node by-node", "Add an Ask a question node."], "verdict": "corrected", "confidence": "medium", "kp": "Generative AI & agentic solutions", "why": "Predictable execution across PolicyWriter and RiskReviewer is the sequential template, which passes the result from one agent to the next in a defined order; group chat routes dynamically. The approval checkpoint for high-risk updates is an Ask a question node, which is what pauses the workflow and waits for the user's input (the human-in-the-loop pattern); an if/else condition on the risk result then routes low-risk updates past that node so they finalize without intervention. A Basic chat node only sends a message to an agent.", "ref": "https://learn.microsoft.com/en-us/azure/foundry/agents/concepts/workflow"},
"1009437": {"exam": "AI-103", "n": 80, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Error rates, run counts, token usage and traces in the Foundry control plane come from Application Insights; until it is enabled for the agent's project nothing is collected, so the views stay empty. A Log Analytics workspace alone, a new version or a restart does not start telemetry."},
"1009438": {"exam": "AI-103", "n": 81, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "prebuilt-documentSearch is the Content Understanding analyzer built for retrieval-augmented generation: it produces Markdown with layout and semantic structure (sections, tables, links) optimized for chunking and indexing. prebuilt-layout returns raw layout, prebuilt-read is OCR, and documentFieldSchema proposes field schemas."},
"1009439": {"exam": "AI-103", "n": 82, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Matching by meaning when the user's wording differs from the manuals requires vector search: embeddings of the chunks are indexed and compared with the query embedding. Semantic ranking only re-ranks keyword results at query time, and suggesters and analyzers work on terms."},
"1009440": {"exam": "AI-103", "n": 83, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Hybrid search runs keyword matching on the searchable text fields, which handles exact product names and codes, together with vector search on the description embeddings, which handles natural-language queries, and fuses the results."},
"1009441": {"exam": "AI-103", "n": 84, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "The Azure Content Understanding skill is the built-in Azure AI Search skill that extracts text and images with location metadata (page numbers and positional data for page-level citations), and it is the one that recognizes tables spanning multiple pages and extracts cross-page tables as a single unit. The Document Layout skill also returns location metadata but outputs tables as plain text and has no cross-page table handling; Document Extraction returns content without layout, and the GenAI Prompt skill describes images with a model.", "ref": "https://learn.microsoft.com/en-us/azure/search/cognitive-search-skill-content-understanding"},
"1009442": {"exam": "AI-103", "n": 85, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Scanned invoices are images with no text layer, so the OCR skill is needed to extract their text before it can be searched. Text Split and Translation work on text that already exists, and Image Analysis describes pictures rather than reading them."},
"1009443": {"exam": "AI-103", "n": 86, "boxes": ["string", "generate"], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "A free-text description of each segment's colour scheme is a string field whose value the model writes, so its method is generate; classify would pick from a fixed set of categories, and group or table are for structured collections."},
"1009444": {"exam": "AI-103", "n": 87, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Comparing an invoice with its purchase order and validating it against static vendor contracts, returning one structured set of findings, is a multi-file task in pro mode: the invoice and purchase order are the inputs and the contracts are reference data. Standard mode has no cross-document reasoning or reference data."},
"1009445": {"exam": "AI-103", "n": 88, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Mask-based inpainting edits only the masked corner and leaves the rest of the video as it was, so the watermark is removed without regenerating. Prompt or guidance changes mean regenerating, and cropping changes the framing."},
"1009446": {"exam": "AI-103", "n": 89, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Multimodal chat models expect the user message content as an array of parts, one of type text and one of type image_url, so the model recognises the image. Base64 inside a text string, metadata or the system message do not deliver an image part."},
"1009447": {"exam": "AI-103", "n": 90, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "The Realtime API supports WebRTC and WebSocket transports; WebRTC is the one designed for low-latency audio streaming from client applications (browsers and mobile), reaching roughly 100 ms, while WebSocket over TCP adds latency and RTMP and SIP are not supported."},
"1009448": {"exam": "AI-103", "n": 91, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "The evaluation is already defined in File1, so the workflow's evaluation action is pointed at that YAML through its evaluation-config input. Endpoint, deployment name and tenant settings support authentication and targets but do not select the evaluation definition."},
"1009449": {"exam": "AI-103", "n": 92, "boxes": ["Enable a system-assigned managed identity at the project level.", "Assign the Key Vault Secrets User role to the managed identity."], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "A system-assigned managed identity on the project gives the agent a keyless identity with the narrowest scope, and the Key Vault Secrets User role lets it read secrets and nothing else. A service principal secret and an API key are both stored credentials, and access policies are the legacy model that grants broader permissions."},
"1009450": {"exam": "AI-103", "n": 93, "boxes": ["No", "Yes", "Yes"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "A lower severity threshold is stricter and flags more content, so it would make the fine-tuning RAI checks fail more, not less. Run1's medium threshold catches more harmful content than Run2's high threshold, which explains 12% against 4%. Protected material detection does not use a severity threshold, so its 6% is unchanged between the runs."},
"1009451": {"exam": "AI-103", "n": 94, "boxes": ["Hierarchical spans", "Tool call attributes"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Nested operations across an agent run are captured as a hierarchy of parent and child spans in the trace. Tool invocation arguments and results are recorded as attributes on the tool call spans. Sampling and KQL filters reduce or query data rather than capture it."},
"1009452": {"exam": "AI-103", "n": 95, "boxes": ["Implement exponential backoff and jitter in the retry logic.", "Split content into smaller files before uploading the files."], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "HTTP 429 is throttling, handled within the existing limits by retrying with exponential backoff and jitter. HTTP 400 file size exceeded is fixed by splitting the content into files that stay under the upload limit. Raising tenant quotas changes the limits, which the requirement rules out."},
"1009453": {"exam": "AI-103", "n": 96, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Vector representations of documents and queries for search come from an embedding model. Language models generate text and image models generate pictures; neither produces search embeddings."},
"1009454": {"exam": "AI-103", "n": 97, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "A serverless API (pay-as-you-go) deployment gives a real-time REST endpoint with key-based authentication on Microsoft-hosted infrastructure, so it uses no virtual machine vCPU quota from the subscription. Managed compute and self-hosted containers consume VM quota, and batch is not real-time."},
"1009455": {"exam": "AI-103", "n": 98, "boxes": ["'AzureKeyVault'", "'AccountManagedIdentity'"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "A connection to a key vault uses the AzureKeyVault category, and the Foundry account authenticates to it with its managed identity (AccountManagedIdentity) rather than a stored key or API key."},
"1009456": {"exam": "AI-103", "n": 99, "boxes": ["Configure revival from approved data sources.", "Enable agent memory that uses persistent storage."], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Grounding only on curated policy documents means configuring retrieval from the approved data sources (the option's \"revival\" is a typo for retrieval) rather than copying files into the agent or pasting them into instructions. Preferences that persist across separate chat sessions need agent memory in persistent storage; session context and client state do not survive a new session."},
"1009457": {"exam": "AI-103", "n": 100, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Improving completeness inside the application code before returning a response means evaluating the draft and retrying when something is missing. Temperature and presence penalty tune randomness and repetition, and a smaller model reduces completeness."},
"1009458": {"exam": "AI-103", "n": 101, "boxes": ["Yes", "Yes", "No"], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "The condition prints only brands with confidence of 0.75 or higher. rectangle.x and rectangle.y are the top-left corner of the bounding box, while w and h are its width and height, not the bottom-right corner, so the third statement is false."},
"1009459": {"exam": "AI-103", "n": 102, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Image generation models such as DALL-E are deployed from the Microsoft Foundry model catalog, and the same deployment can be created with the Azure CLI. SDKs are for calling a deployed model, Machine Learning studio does not deploy Azure OpenAI models, and Microsoft Graph is unrelated."},
"1009460": {"exam": "AI-103", "n": 103, "boxes": ["OpenAI", "--encryption"], "verdict": "corrected", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Generating fictional stories from prompts needs an Azure OpenAI account, so the kind is OpenAI. The JSON with keySource and keyVaultProperties is the value of the --encryption parameter of az cognitiveservices account create; --assign-identity takes no value and --api-properties is for service-specific settings such as QnA Maker or Bing."},
"1009461": {"exam": "AI-103", "n": 104, "boxes": ["AnalyzeTextOptions(text=comment)", "client.analyze_text(request)"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "The Content Safety Python SDK builds the request with AnalyzeTextOptions(text=comment) and runs it with client.analyze_text(request); the categories_analysis in the response then holds the self-harm severity."},
"1009462": {"exam": "AI-103", "n": 105, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "One entity that mixes phone numbers, email addresses and social handles gives the model three unrelated patterns to learn, which causes false positives. Splitting it into Phone, Email and SocialMedia entities and relabelling makes each entity consistent and improves precision. Lowering the threshold or auto-labelling adds false positives, and more data with the same mixed label repeats the problem."},
"1009463": {"exam": "AI-103", "n": 106, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "SSML phoneme elements spell out exactly how a technical term should be pronounced, which fixes mispronunciations with a few lines of markup. say-as controls interpretation of numbers and dates, prosody changes pitch and rate, a custom voice is far more effort, and Whisper is speech recognition."},
"1009464": {"exam": "AI-103", "n": 107, "boxes": ["No", "Yes", "Yes"], "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "piiCategories limits detection to Person and PhoneNumber, so the audit list contains only those entities, not the email or SSN. Because the email and SSN are not detected they stay unredacted in the text for the model, while the name and phone number are replaced by entity-type masks."},
"1009465": {"exam": "AI-103", "n": 108, "boxes": ["Create a project.", "Upload and tag images.", "Train the classifier model."], "verdict": "corrected", "confidence": "medium", "kp": "Computer vision solutions", "why": "Detecting whether a component is faulty is image classification: each image is tagged as faulty or good. In Custom Vision you create the project, upload and tag the images, then train the classifier. Object detection is for locating objects with bounding boxes, and there is no separate dataset initialization step."},
"1009466": {"exam": "AI-103", "n": 109, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Telling users that their data has been processed by the system is the transparency principle: people should understand how AI systems use their data. Fairness, inclusiveness and reliability address bias, accessibility and safe operation."},
"1009467": {"exam": "AI-103", "n": 110, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "Immersive Reader is the Azure AI service built for reading comprehension and accessibility, with text spacing, syllables, line focus and read-aloud for readers with dyslexia and other learning differences, embedded with minimal code. Document Intelligence, Language and Translator serve other purposes."},
"1009468": {"exam": "AI-103", "n": 111, "answer": "A", "verdict": "confirmed", "confidence": "medium", "kp": "Planning & managing Azure AI solutions", "why": "With administrative effort as the deciding requirement, the endpoint URI and a subscription key configure the app in two settings with nothing else to provision. OAuth tokens need an identity setup, SAS tokens are not used by Foundry resources, and certificates add management work; keyless Entra access is the more secure choice but not the least effort."},
"1009469": {"exam": "AI-103", "n": 112, "boxes": ["Add a new query key", "Change the app to use the new key", "Delete the compromised key"], "verdict": "corrected", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "To keep the app running, create a new query key first, switch the app to it, and only then delete the compromised key; deleting first would break the app until the new key is in place. Query keys give read-only access to the documents collection, so admin keys are not involved."},
"1009470": {"exam": "AI-103", "n": 113, "boxes": ["PUT", "CognitiveServices"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Creating an Azure resource through Azure Resource Manager is a PUT to the resource's URI. A single key and endpoint for several services with consolidated billing, including Vision later, is the multi-service resource, whose kind is CognitiveServices rather than a single-service kind."},
"1009471": {"exam": "AI-103", "n": 114, "boxes": ["0", "25"], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Precision of 100% means every detection was correct, so the false positive rate is 0. True positives divided by true positives plus false negatives is recall, which the exhibit reports as 25%."},
"1009472": {"exam": "AI-103", "n": 115, "answer": "AEF", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "Document-level security in Azure AI Search is built by tagging each document with the groups allowed to see it, looking up the groups of the signed-in user, and passing those groups as a filter on each search request. One index per group does not scale, and the service does not evaluate Entra tokens by itself."},
"1009473": {"exam": "AI-103", "n": 116, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "The Azure Content Understanding skill is the built-in multimodal content extraction skill that returns text and images with location metadata (page numbers and positional data) and recognizes tables that span multiple pages, extracting cross-page tables as a single unit. Document Layout also provides location metadata but outputs tables as plain text with no cross-page handling; Document Extraction has no layout, and GenAI Prompt describes images.", "ref": "https://learn.microsoft.com/en-us/azure/search/cognitive-search-skill-content-understanding"},
"1009474": {"exam": "AI-103", "n": 117, "boxes": ["Object projection", "Object projection"], "verdict": "corrected", "confidence": "medium", "kp": "Information extraction solutions", "why": "Knowledge store object projections write enriched documents as JSON blobs, which suits both the unstructured JSON data and the text extracted from scanned PDFs. Table projections need a relational shape that the question does not define, and file projections are for normalized binary images.", "ref": "https://learn.microsoft.com/en-us/azure/search/knowledge-store-projection-overview"},
"1012319": {"exam": "AI-103", "n": 118, "boxes": ["Classification", "Multiclass (Single tag per image)", "General (compact)"], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Deciding whether a picture shows a cat or a dog is classification with one tag per image, so multiclass. Compact domains produce models that can be exported to run inside an iOS app."},
"1012320": {"exam": "AI-103", "n": 119, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "tool_choice is the run parameter that forces the agent to call a tool (set to required, or to the kbsearch tool) on every run. response_format shapes the output, toolset only makes tools available, and changing the run method does not force tool use."},
"1012321": {"exam": "AI-103", "n": 120, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "recognize_entities returns named entities, and in the sentence the entities are the locations London and Buckingham Palace; tour and visit are ordinary nouns."},
"1012322": {"exam": "AI-103", "n": 121, "boxes": ["No", "No", "Yes"], "verdict": "corrected", "confidence": "high", "kp": "Text analysis solutions", "why": "recognize_linked_entities links entities to a knowledge base; it does not detect language. Each linked entity's url points to the entity's data source page, typically Wikipedia, not to a Bing search. The matches collection gives the text and offset of each place the entity appears in the document."},
"1012323": {"exam": "AI-103", "n": 122, "boxes": ["Use model catalog leaderboards and model cards.", "Use a serverless deployment."], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Model catalog leaderboards and model cards compare candidate models on quality, cost and throughput before deployment. A serverless (pay-as-you-go) deployment keeps the model weights on Microsoft-managed infrastructure, whereas managed compute hosts them in your subscription."},
"1012324": {"exam": "AI-103", "n": 123, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Information extraction solutions", "why": "An embeddings model returns numeric vectors for text, which are compared to measure semantic similarity between documents. GPT models generate text and DALL-E generates images."},
"1012325": {"exam": "AI-103", "n": 124, "boxes": ["No", "Yes", "Yes"], "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "\"LLM\" is ambiguous (it is also a law degree) and a generic system message gives no context, so the answer is not certain to be about language models. Adding \"in the context of AI models\" to the question disambiguates it, and a system message that restricts answers to AI language models raises the likelihood of the intended response."},
"1012326": {"exam": "AI-103", "n": 125, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "The Azure OpenAI SDK connects with the resource endpoint, a key (or token) and the deployment name, which identifies the deployed model. The underlying model name or type is not part of the connection."},
"1012327": {"exam": "AI-103", "n": 126, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Virtual network rules on the Language resource's networking settings allow traffic only from selected subnets, so only the designated Azure workloads can reach it, with no extra infrastructure. Gateways, Application Gateway and IPsec address connectivity, not access restriction on the resource."},
"1012328": {"exam": "AI-103", "n": 127, "answer": "AC", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Restricting the Foundry resource to specific resources means enabling the Cognitive Services service endpoint on the VNet1 subnet and then, in CSAccount1's networking (virtual network) settings, allowing only that subnet, which also blocks public access. IAM controls who, not where, and creating or editing VNet1 itself does not restrict the account."},
"1012329": {"exam": "AI-103", "n": 128, "boxes": ["Azure Document Intelligence in Foundry Tools", "Azure Language in Foundry Tools"], "verdict": "confirmed", "confidence": "medium", "kp": "Text analysis solutions", "why": "Text in PDF documents is extracted with Document Intelligence (its read model handles PDFs and scanned pages), and sentiment analysis is a feature of the Language service. Azure AI Search indexes content rather than analysing it, and Vision targets images."},
"1012330": {"exam": "AI-103", "n": 129, "answer": "C", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Custom Vision trains a model from your own approved and rejected product images with no code and can then classify frames from the video feed to flag defects. Azure Vision's prebuilt models cannot learn your products, Video Indexer indexes media, and Azure Machine Learning needs far more development."},
"1012331": {"exam": "AI-103", "n": 130, "boxes": ["No", "Yes", "Yes"], "verdict": "corrected", "confidence": "medium", "kp": "Planning & managing Azure AI solutions", "why": "The container's /status endpoint checks that the API key is valid without sending a query to the Azure endpoint. Container logs are written by the default logging provider (console) even when no logging settings are passed. The /swagger endpoint serves the documentation for the container's REST API.", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/language-service/sentiment-opinion-mining/how-to/use-containers"},
"1012332": {"exam": "AI-103", "n": 131, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "A Microsoft Foundry (multi-service) resource exposes Speech, Language and other services through one endpoint and one key. Single-service Language or Speech resources each have their own endpoint and credential."},
"1012333": {"exam": "AI-103", "n": 132, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "Microsoft's guidance is to use Document Intelligence's read model for text-heavy documents such as scanned articles, books and reports, and the Vision Read API for text in natural scenes such as signs and posters; both are prebuilt, but Document Intelligence handles document pages and large batches with the least custom work.", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/computer-vision/overview-ocr"},
"1012334": {"exam": "AI-103", "n": 133, "boxes": ["Provision an on-premises Kubernetes cluster that has internet connectivity.", "Pull an image from the Microsoft Container Registry (MCR).", "Run the container and specify an API key and the Endpoint URL of the Azure AI resource."], "verdict": "corrected", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Azure AI Language containers keep the documents on-premises but must reach Azure to report billing, so the cluster needs internet connectivity. The images are published in the Microsoft Container Registry, not Docker Hub, and the container starts with the resource's API key and endpoint (plus Eula=accept).", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/language-service/sentiment-opinion-mining/how-to/use-containers"},
"1012335": {"exam": "AI-103", "n": 134, "boxes": ["POST", "imageType"], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "The Vision analyze operation is a POST that carries the image (or its URL) in the body, and the imageType visual feature returns scores for clip art and line drawing."},
"1012336": {"exam": "AI-103", "n": 135, "answer": "CE", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "After training, Custom Vision reports precision and recall (and mean average precision for object detection). F-score, AUC and weighted accuracy are not shown."},
"1018720": {"exam": "AI-103", "n": 136, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Access to the Language resource is restricted in its own networking settings by allowing only vnet1's subnets (through a service endpoint or private endpoint). NSGs, Azure Firewall and containers do not limit who can call the resource."},
"1018721": {"exam": "AI-103", "n": 137, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Moderate text content in Content Safety Studio lets you run sample text through the filters, see the severity scores per category and adjust the thresholds, which is how filter configurations are tuned before deployment."},
"1018722": {"exam": "AI-103", "n": 138, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "The safety metaprompt feature provides system-message guidance for safer model behaviour; it does not run sample questions through the content filters or tune thresholds."},
"1018723": {"exam": "AI-103", "n": 139, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Protected material detection looks for copyrighted text or code; it does not test or tune the harmful-content filter configuration."},
"1018724": {"exam": "AI-103", "n": 140, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Monitor online activity shows usage statistics of the deployed moderation APIs; it is not a tool for running sample questions or adjusting filter thresholds."},
"1018725": {"exam": "AI-103", "n": 141, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Decisions that affect people's finances must keep a human accountable, so a human review and approval step before bonuses are set follows the accountability and fairness principles. Using low-confidence results, data from customers who asked for deletion, or exposing raw survey data would breach reliability, privacy and security."},
"1018726": {"exam": "AI-103", "n": 142, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "az cognitiveservices account show returns the details of a named Azure AI services account in a resource group, which identifies the account the pipeline created. network-rule manages firewall rules, az account list lists subscriptions, and az resource link relates resources."},
"1018727": {"exam": "AI-103", "n": 143, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Spatial Analysis in Azure AI Vision analyses live video to detect and count people in a zone, so it can verify that only one person is in front of the camera without custom model training. Video Indexer moderation, speech to text and Custom Vision object detection do not count people in real time out of the box."},
"1018728": {"exam": "AI-103", "n": 144, "answer": "AD", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "The Read operation is asynchronous, so the code must poll get_read_result in a loop with a delay and check read_result.status until it is no longer running or not started. The operation_id is required, and the Operation-Location header is just the URL from which the id is taken."},
"1018729": {"exam": "AI-103", "n": 145, "answer": "A", "verdict": "corrected", "confidence": "medium", "kp": "Planning & managing Azure AI solutions", "why": "The security requirement names a specific threat: product-sheet images may carry hidden malicious instructions, an indirect prompt-injection attack that Prompt Shields detect and block. Protected material detection finds copyrighted text, and the violence and self-harm filters address harmful content categories.", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/content-safety/concepts/jailbreak-detection"},
"1018730": {"exam": "AI-103", "n": 146, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Personalized interactions that retain context and recall earlier interactions are provided by agent memory. Instructions set behaviour, tools perform actions, and guardrails restrict content."},
"1018731": {"exam": "AI-103", "n": 147, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Content sent to the MCP server travels in the tool call, so a guardrail at the tool call intervention point can block violent content before it leaves the agent. User input and output are the conversation ends, and tool response is what comes back from the server."},
"1018732": {"exam": "AI-103", "n": 148, "boxes": ["AnalyzeTextOptions", "client.analyze_text"], "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "Analysing text against an existing blocklist uses AnalyzeTextOptions with blocklist_names and halt_on_blocklist_hit, executed by client.analyze_text. The blocklist item operations manage the list itself rather than analyse input."},
"1018733": {"exam": "AI-103", "n": 149, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Suggesting product names from a description is text generation, which a GPT-4 model does. Whisper transcribes audio, DALL-E makes images, and embeddings produce vectors."},
"1018734": {"exam": "AI-103", "n": 150, "boxes": ["Object detection", "General (compact)"], "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Locating defects and counting the four products in each package needs bounding boxes, so the project is object detection. With intermittent connectivity the model must run on site, which requires an exportable compact domain, General (compact)."},
"1018735": {"exam": "AI-103", "n": 151, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "Adding a short comment asking what the function does makes the prompt an explanation request at the cost of a few tokens on the cheaper GPT-3.5 Turbo model. Switching to GPT-4-32k costs more, temperature changes randomness, and a function stub asks for nothing."},
"1018736": {"exam": "AI-103", "n": 152, "boxes": ["From the Custom Vision portal, open the project.", "Upload sample images of the new products.", "Label the sample images.", "Retrain the model.", "Publish the model."], "verdict": "corrected", "confidence": "high", "kp": "Computer vision solutions", "why": "A Custom Vision classifier is maintained in the Custom Vision portal: open the project, upload images of the new products, tag them, retrain, and publish the new iteration so the app uses it. Vision Studio and Azure Machine Learning studio do not manage Custom Vision projects."},
"1018737": {"exam": "AI-103", "n": 153, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Generative AI & agentic solutions", "why": "A reflection pass in the application code checks the generated summary for missing content and regenerates before returning it, which improves completeness. Streaming, presence penalty and fewer tokens do not."},
"1018738": {"exam": "AI-103", "n": 154, "boxes": ["An API key", "A deployment name"], "verdict": "corrected", "confidence": "medium", "kp": "Planning & managing Azure AI solutions", "why": "Apps calling the resource's REST API authenticate with the resource's API key, which, kept only in the three apps, limits access to them. Each app reaches its tuned deployment by putting that deployment's name in the request path; deployments share the resource endpoint and have no separate endpoint or type to connect with."},
"1018739": {"exam": "AI-103", "n": 155, "answer": "D", "verdict": "confirmed", "confidence": "high", "kp": "Planning & managing Azure AI solutions", "why": "The Keys and Endpoint blade of the Language resource shows its REST endpoint URL together with the access keys. Properties, Identity and Networking show other settings."},
"1018740": {"exam": "AI-103", "n": 156, "boxes": ["Create a private endpoint.", "Use Azure roles."], "verdict": "corrected", "confidence": "high", "kp": "Information extraction solutions", "why": "A private endpoint puts Search1 on the virtual network and public access can be disabled, which keeps it off the internet. Per-index access for each app comes from Azure RBAC data-plane roles such as Search Index Data Reader scoped to individual indexes; API keys grant access to every index, and an IP firewall does not isolate from the internet."},
"1018741": {"exam": "AI-103", "n": 157, "answer": "A", "verdict": "confirmed", "confidence": "high", "kp": "Computer vision solutions", "why": "Image Analysis in Azure AI Vision generates tags for an image and accepts a language parameter, so English, French and Spanish tags come from the one prebuilt endpoint. Custom Vision needs training, Content Safety moderates, and Custom Translator translates text."},
"1018742": {"exam": "AI-103", "n": 158, "boxes": ["Request approval to run the container.", "Export model1 to Host1.", "Run the container."], "verdict": "corrected", "confidence": "high", "kp": "Text analysis solutions", "why": "Speech containers were gated, so the exam expects access to be requested and approved first (today only disconnected containers need an approved request). The custom model is then made available to the host (the container downloads it by ModelId into the mounted volume), and the container is run with the model plus the billing endpoint and key. Retraining is not needed, and disk logging is optional.", "ref": "https://learn.microsoft.com/en-us/azure/ai-services/speech-service/speech-container-cstt"},
"1018743": {"exam": "AI-103", "n": 159, "answer": "B", "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "Question answering in the Azure AI Language service builds a knowledge base from the HR PDFs and returns the same stored answer for a matched question every time, with no code. Azure OpenAI generates a different wording each time, and Document Intelligence or Machine Learning do not answer questions."},
"1018744": {"exam": "AI-103", "n": 160, "boxes": ["Azure Vision in Foundry Tools", "Azure Language in Foundry Tools"], "verdict": "corrected", "confidence": "medium", "kp": "Text analysis solutions", "why": "Text on road signs in photographs is read with Azure AI Vision's OCR, which is built for text in natural scenes. Identifying well-known locations in the extracted text is named entity recognition and entity linking in the Language service. Document Intelligence targets documents, and Azure AI Search indexes content rather than analysing it."},
"1018745": {"exam": "AI-103", "n": 161, "boxes": ["mcr.microsoft.com/azure-cognitive-services/textanalytics/sentiment", "http://contoso.cognitiveservices.azure.com"], "verdict": "confirmed", "confidence": "high", "kp": "Text analysis solutions", "why": "The sentiment analysis container image comes from the Microsoft Container Registry under textanalytics/sentiment, and the Billing argument is the endpoint URI of the Language resource (the question configures https://contoso.cognitiveservices.azure.com; the option shows it with http)."}
};
